  {step:"只读盘点 Task Bundle、HANDOFF、历史约束与六项目仓库身份", status:"in_progress"},
  {step:"整理并确认安全 L2 surface 设计、隐私边界与逐项目验收矩阵", status:"pending"},
  {step:"形成受控实施计划与逐项目 Run Contract", status:"pending"},
