  {step:"清理 branch/PR、同步 GitHub main、生成最终证据与 handoff", status:"pending"}
];
const r = await tools.update_plan({explanation:"目标已由 /goal 激活；先执行 Task Bundle 的只读证据盘点，未触碰生产状态。", plan});
text(r);

const cwd="[REDACTED_LOCAL_PATH]";
const zip="[REDACTED_LOCAL_PATH]";
const cmds=[
  ["zip",`shasum -a 256 ${JSON.stringify(zip)} && unzip -Z1 ${JSON.stringify(zip)}`,cwd,20000],
  ["handoff",`rg --files -g 'HANDOFF.md' -g '!node_modules' -g '!vendor' .`,cwd,10000],
  ["workspace",`pwd && find . -maxdepth 2 -mindepth 1 -print`,cwd,12000],
  ["git",`git status --short --branch && git remote -v`,cwd,10000],
  ["memory",`rg -n -i 'Cloudflare|LinzeHomeHub|Archive/nab|OpenAIDatabase|PFI|Serenity-Alipay|EEI' [REDACTED_LOCAL_PATH]
  ["codexref",`rg --files [REDACTED_LOCAL_PATH] | rg '/codex-tools\\.md$'`,cwd,10000]
];
const rs=await Promise.all(cmds.map(async ([name,cmd,wd,max])=>({name,r:await tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:max})})));
for(const {name,r} of rs){text(`${name}\n${r.output}`)}

const cwd="[REDACTED_LOCAL_PATH]";
const ref="[REDACTED_LOCAL_PATH]";
const out=`${cwd}/work/task_bundle`;
const ex=await tools.exec_command({cmd:`mkdir -p ${JSON.stringify(out)} && unzip -o [REDACTED_LOCAL_PATH] -d ${JSON.stringify(out)}`,workdir:cwd,yield_time_ms:10000,max_output_tokens:5000});
text(ex.output);
