const cwd="[REDACTED_LOCAL_PATH]";
const cmds=[
  ["tools",`git --version && gh --version | head -n 1 && node --version && npm --version && (command -v wrangler || true)`,cwd,5000],
  ["ghauth",`gh auth status`,cwd,10000],
  ["repos",`for repo in LinzeColin/CodexProject LinzeColin/LinzeHomeHub LinzeColin/Archive; do gh repo view "$repo" --json nameWithOwner,defaultBranchRef,isPrivate,url; done`,cwd,10000],
