];
const rs=await Promise.all(cmds.map(async ([name,cmd,wd,max])=>({name,r:await tools.exec_command({cmd,workdir:wd,yield_time_ms:30000,max_output_tokens:max})})));
for(const {name,r} of rs){text(`${name}\nexit=${r.exit_code}\n${r.output}`)}

const cwd="[REDACTED_LOCAL_PATH]";
const repos=["CodexProject","LinzeHomeHub","Archive"];
const ps=repos.map(name=>tools.exec_command({
  cmd:`GIT_TERMINAL_PROMPT=0 git ls-remote --symref http[REDACTED_LOCAL_PATH] HEAD`,
