  echo WRANGLER_AUTH_AVAILABLE
else
  echo WRANGLER_AUTH_UNAVAILABLE
fi
env | sed 's/=.*//' | rg '^CLOUDFLARE_(API_TOKEN|ACCOUNT_ID)$' || true`,
  workdir:cwd,yield_time_ms:30000,max_output_tokens:3000
});
const all=await Promise.all([...ps,cf]);
repos.forEach((name,i)=>text(`${name}\nexit=${all[i].exit_code}\n${all[i].output}`));
text(`Cloudflare\nexit=${all[3].exit_code}\n${all[3].output}`);

