export type ModeId = 'archive' | 'nebula' | 'voyage' | 'garden';

export type ModelId = 'armillary' | 'island' | 'book' | 'compass' | 'garden' | 'core';

export type GravityDirection = 'idle' | 'up' | 'down' | 'side';

export type QualityName = 'low' | 'medium' | 'ultra';

export type Project = {
  id: string;
  name: string;
  category: string;
  status: string;
  summary: string;
  liveUrl: string;
  fallbackUrl: string;
  mode: ModeId;
};

export type PointerState = {
  x: number;
  y: number;
  active: boolean;
};

export type ScrollGravityState = {
  direction: GravityDirection;
  velocityY: number;
  velocityX: number;
  gravityX: number;
  gravityY: number;
  energy: number;
  spaceActive: boolean;
};
[
  {
    "id": "memory-atlas",
    "name": "MemoryAtlas",
    "category": "Memory System",
    "status": "Live / Public",
    "summary": "一个面向长期记忆、上下文和知识关系的交互式可视化系统。",
    "liveUrl": "http[REDACTED_LOCAL_PATH]",
    "fallbackUrl": "http[REDACTED_LOCAL_PATH]",
    "mode": "nebula"
  },
  {
    "id": "openai-database",
    "name": "OpenAIDatabase",
    "category": "Knowledge Database",
    "status": "Mature / Local-first",
    "summary": "本地优先的个人长期记忆数据库工程，提供脱敏派生数据与记忆可视化入口。",
    "liveUrl": "",
    "fallbackUrl": "http[REDACTED_LOCAL_PATH]",
    "mode": "archive"
  }
]
import type { Project } from '../types';

const resolveHref = (project: Project) => project.liveUrl || project.fallbackUrl;

export function renderProjects(projects: Project[], container: HTMLElement): void {
  container.innerHTML = '';
  for (const project of projects) {
    const anchor = document.createElement('a');
    anchor.className = 'planet-card';
    anchor.href = resolveHref(project);
    anchor.target = '_blank';
    anchor.rel = 'noopener noreferrer';
    anchor.dataset.tilt = '';
    anchor.dataset.projectMode = project.mode;
    anchor.setAttribute('aria-label', `进入 ${project.name} 项目前端`);

    const label = document.createElement('span');
    label.className = 'label';
    label.textContent = `${project.category} / ${project.status}`;

    const title = document.createElement('h3');
    title.textContent = project.name;

    const summary = document.createElement('p');
    summary.textContent = project.summary;

    const enter = document.createElement('span');
    enter.className = 'enter-copy';
    enter.textContent = 'Enter Project Frontend';

    anchor.append(label, title, summary, enter);
    container.append(anchor);
  }
}

