  const oldLine = out.output.replace(/\n$/,"");
  const newLine = oldLine.replace(prefix,replacementPrefix);
  const patch = `*** Begin Patch\n*** Update File: ${root}/${rel}\n@@\n-${oldLine}\n+${newLine}\n*** End Patch`;
