}
text("updated parameter model/formula bindings");

const root = "[REDACTED_LOCAL_PATH]";
const projects = ["EEI","OpenAIDatabase","PFI","Serenity-Alipay"];
const results = await Promise.all(projects.map(project => tools.exec_command({
  cmd:`python3 scripts/validate_project_governance.py --project '${project}' --semantic`,
  workdir:root,
  yield_time_ms:30000,
  max_output_tokens:60000
})));
const treeResult = await tools.exec_command({cmd:"git ls-tree -r --name-only HEAD",workdir:root,yield_time_ms:10000,max_output_tokens:100000});
const treeFiles = new Set(treeResult.output.split("\n").filter(Boolean));
const toAdd = new Set([
  ".agents/skills/codex-dex/SKILL.md",
  "Alpha/AGENTS.md","FIFA/AGENTS.md","KM_IDSystem/AGENTS.md","WDA/AGENTS.md",
  "MetaDatabase/README.md","KMFA/AGENTS.md","QBVS/AGENTS.md","whkmSalary/AGENTS.md","arxiv-daily-push/AGENTS.md"
]);
const counts = {};
for (let i=0;i<projects.length;i++) {
  const lines = results[i].output.split("\n");
  let seen = 0;
  for (const line of lines) {
    const m = line.match(/(?:points to missing path|Missing file:|Registered project path missing:|Project path missing:)\s+(.+)$/i);
    if (!m) continue;
    let candidate = m[1].trim().replace(/^["'`]|["'`]$/g,"");
    candidate = candidate.replace(/:\d+(?:-\d+)?$/,"");
    if (treeFiles.has(candidate)) {
      toAdd.add(candidate);
      seen++;
    }
  }
  counts[projects[i]] = {exit:results[i].exit_code, matched_refs:seen};
}
const paths = [...toAdd].filter(p=>treeFiles.has(p)).sort();
const quote = s => "'" + s.replace(/'/g,"'\\''") + "'";
for (let i=0;i<paths.length;i+=120) {
  const batch = paths.slice(i,i+120);
  const add = await tools.exec_command({cmd:`git sparse-checkout add ${batch.map(quote).join(" ")}`,workdir:root,yield_time_ms:30000,max_output_tokens:12000});
  if (add.exit_code !== 0) throw new Error(add.output);
}
text(JSON.stringify({counts,unique_paths_materialized:paths.length},null,2));

