let patch="*** Begin Patch\n";
files.forEach((f,i)=>{
 const old=lines[i]; const obj=JSON.parse(old); const p=projects[i];
 obj.files_changed=[
  `${p}/docs/governance/ASSURANCE_STATUS.yaml`,
  `${p}/docs/governance/OWNER_STATUS.md`,
  `${p}/docs/governance/STATUS.md`,
  `${p}/docs/governance/development_events.jsonl`,
  `${p}/docs/governance/project.yaml`,
  `${p}/docs/governance/roadmap.yaml`,
  `${p}/功能清单.md`,
  `${p}/开发记录.md`,
  `${p}/模型参数文件.md`
 ];
 patch+=`*** Update File: ${root}/${f}\n@@\n-${old}\n+${JSON.stringify(obj)}\n`;
});
patch+="*** End Patch"; text(await tools.apply_patch(patch));

