const r = await tools.exec_command({
  cmd: "for project in EEI OpenAIDatabase PFI Serenity-Alipay; do python3 scripts/generate_governance_dashboard.py --write --project \"$project\" || exit 1; done",
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 30000,
  max_output_tokens: 10000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "for project in EEI OpenAIDatabase PFI Serenity-Alipay; do output=$(python3 scripts/lean_governance.py check-render --project \"$project\"); printf '%s\\n' \"$output\"; printf '%s\\n' \"$output\" | jq -e '.drift_count == 0 and .reference_issue_count == 0' >/dev/null || exit 1; done\nfor project in EEI OpenAIDatabase PFI Serenity-Alipay; do python3 scripts/validate_project_governance.py --project \"$project\" || exit 1; done\npython3 -m unittest tests.cloudflare.test_compatibility_envelope tests.governance.test_cloudflare_compatibility_envelope -v\npython3 scripts/cloudflare/validate_compatibility_envelope.py\ngit diff --check",
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 30000,
  max_output_tokens: 20000
});
text(r.output);
if (r.session_id) text(JSON.stringify({session_id:r.session_id}));

const r = await tools.exec_command({
  cmd: "sed -n '35,75p' EEI/docs/governance/project.yaml && sed -n '30,60p' Serenity-Alipay/docs/governance/project.yaml && sed -n '30,55p' OpenAIDatabase/docs/governance/project.yaml",
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 10000,
  max_output_tokens: 6000
});
text(r.output);

