  cmd: "for project in EEI OpenAIDatabase PFI Serenity-Alipay; do printf '%s\\n' \"$project\"; rg -n 'governance/cloudflare|FINAL_ACCEPTANCE_BUNDLE|apps/cloudflare-public|apps/memory-atlas|web/cloudflare-public|app/cloudflare-public' \"$project/docs/governance/roadmap.yaml\"; done",
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 10000,
  max_output_tokens: 12000
});
text(r.output);

const root="[REDACTED_LOCAL_PATH]";
const cfgs=[
 {file:"EEI/docs/governance/roadmap.yaml",full:"EEI/apps/cloudflare-public",rel:"apps/cloudflare-public"},
 {file:"OpenAIDatabase/docs/governance/roadmap.yaml",full:"OpenAIDatabase/apps/memory-atlas",rel:"apps/memory-atlas"},
 {file:"PFI/docs/governance/roadmap.yaml",full:"PFI/web/cloudflare-public",rel:"web/cloudflare-public"},
 {file:"Serenity-Alipay/docs/governance/roadmap.yaml",full:"Serenity-Alipay/app/cloudflare-public",rel:"app/cloudflare-public"}
];
function hunk(oldLines,newLines){return "@@\n"+oldLines.map(x=>"-"+x).join("\n")+"\n"+newLines.map(x=>"+"+x).join("\n")+"\n";}
let patch="*** Begin Patch\n";
for(const c of cfgs){
 patch+=`*** Update File: ${root}/${c.file}\n`;
 patch+=hunk(
  [`        - "${c.full}"`,`        - "governance/cloudflare/deployments.json"`,'        - "FINAL_ACCEPTANCE_BUNDLE/cloudflare_compatibility_envelope/FINAL_REPORT.md"'],
  [`        - "${c.rel}"`,'        - "docs/governance/development_events.jsonl"','        - "docs/governance/project.yaml"']);
 patch+=hunk(
  ['            - "governance/cloudflare/deployments.json"','            - "FINAL_ACCEPTANCE_BUNDLE/cloudflare_compatibility_envelope/deployments.md"'],
  ['            - "docs/governance/development_events.jsonl"','            - "docs/governance/project.yaml"']);
 patch+=hunk(
  ['                  - "governance/cloudflare/deployments.json"','                  - "FINAL_ACCEPTANCE_BUNDLE/cloudflare_compatibility_envelope/FINAL_REPORT.md"'],
  ['                  - "docs/governance/development_events.jsonl"','                  - "docs/governance/project.yaml"']);
 patch+=hunk(
  [`              - "${c.full}"`,'              - "governance/cloudflare/deployments.json"','              - "FINAL_ACCEPTANCE_BUNDLE/cloudflare_compatibility_envelope/deployments.md"'],
  [`              - "${c.rel}"`,'              - "docs/governance/development_events.jsonl"','              - "docs/governance/project.yaml"']);
}
patch+="*** End Patch"; text(await tools.apply_patch(patch));

