git diff --check
python3 scripts/lean_governance.py ci --changed-only --base-ref origin/main`,
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 30000,
  max_output_tokens: 5000
});
text(r);

const r = await tools.exec_command({
  cmd: `python3 - <<'PY'\nimport json\np='.git/codex-review/lean-governance/ci-[REDACTED_PHONE]-d47fb55ab2b1-9a6d469e.json'\nd=json.load(open(p))\nfor line in d['validation']['output']:\n    if 'ERROR' in line or line.startswith('errors:') or line.startswith('projects changed:'):\n        print(line)\nPY`,
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 10000,
  max_output_tokens: 2500
});
text(r.output);

const r = await tools.exec_command({
  cmd: `set -e
git add governance/run_manifests/CF-L[REDACTED_PHONE].json
git diff --cached --check
git commit -m "Clarify Cloudflare evidence commit semantics"
git push origin main`,
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 30000,
  max_output_tokens: 5000
});
text(r);

const r = await tools.exec_command({
  cmd: "python3 scripts/lean_governance.py ci --changed-only --base-ref origin/main",
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 30000,
  max_output_tokens: 5000
});
text(r);

const r = await tools.mcp__node_repl__js({title:"清理 Cloudflare 授权页面",code:`var chromeTabsForCleanup = await chromeCf.tabs.list(); for (const t of chromeTabsForCleanup) { try { await (await chromeCf.tabs.get(t.id)).close(); } catch {} } await chromeCf.tabs.finalize({keep:[]}); nodeRepl.write({closed:chromeTabsForCleanup.length});`});
for (const c of (r?.content ?? [])) {
  if (c.type === "text") text(c.text);
  else if (c.type === "image") image(c);
}

const r = await tools.mcp__node_repl__js({title:"清理内置浏览器页面",code:`await browser.tabs.finalize({keep:[]}); nodeRepl.write("finalized");`});
for (const c of (r?.content ?? [])) {
  if (c.type === "text") text(c.text);
  else if (c.type === "image") image(c);
}

