const repo="[REDACTED_LOCAL_PATH]";
const cmd=String.raw`python3 - <<'PY'
import collections, json, os, re, statistics, subprocess

tree=subprocess.check_output(["git","-c","core.quotepath=false","ls-tree","-r","-l","-z","HEAD","OpenAIDatabase"])
rows=[]
for item in tree.split(b"\0"):
    if not item: continue
    meta,pb=item.split(b"\t",1); parts=meta.split()
    if len(parts)<4 or parts[1]!=b"blob": continue
    p=pb.decode(); rel=p.removeprefix("OpenAIDatabase/")
    rows.append({"path":p,"rel":rel,"oid":parts[2].decode(),"size":int(parts[3])})
lookup={r["rel"]:r for r in rows}

def lines_for(rel):
    b=subprocess.check_output(["git","cat-file","blob",f"HEAD:OpenAIDatabase/{rel}"])
    return b.count(b"\n")+(0 if not b or b.endswith(b"\n") else 1)

def line_stats(items):
    vals=[(r["rel"],lines_for(r["rel"]),r["size"]) for r in items]
    return {
      "files":len(vals),"total_lines":sum(v[1] for v in vals),
      "median_lines":statistics.median([v[1] for v in vals]) if vals else 0,
      "max_lines":max((v[1] for v in vals),default=0),
      "top10":[{"path":p,"lines":n,"bytes":b} for p,n,b in sorted(vals,key=lambda x:(-x[1],x[0]))[:10]]
    }

root_scripts=[r for r in rows if r["rel"].startswith("scripts/") and re.search(r"\.(py|sh|zsh|js|mjs|cjs)$",r["rel"])]
validators=[r for r in rows if re.match(r"apps/memory-atlas/scripts/validate_.*\.(cjs|mjs|js)$",r["rel"])]

pkg=json.loads(subprocess.check_output(["git","show","HEAD:OpenAIDatabase/apps/memory-atlas/package.json"]))
scripts=pkg.get("scripts",{})
cmd_groups=collections.defaultdict(list)
for k,v in scripts.items(): cmd_groups[v].append(k)
dup_cmds=[{"command":cmd,"aliases":names} for cmd,names in cmd_groups.items() if len(names)>1]

oid_groups=collections.defaultdict(list)
for r in rows:
    if r["rel"].startswith(("data/raw_archives/","session_history/")): continue
    oid_groups[r["oid"]].append(r)
dups=[g for g in oid_groups.values() if len(g)>1]
dups_sorted=sorted(dups,key=lambda g:(-(len(g)-1)*g[0]["size"],g[0]["rel"]))

out={
 "line_stats":{"root_scripts":line_stats(root_scripts),"validators":line_stats(validators)},
 "package_scripts":{
   "total":len(scripts),
   "validate_prefix":sum(k.startswith("validate:") for k in scripts),
   "unique_commands":len(cmd_groups),
   "duplicate_command_groups":len(dup_cmds),
   "duplicate_aliases":dup_cmds[:30],
   "v1_1_6":sum(k.startswith("validate:v1.1.6") for k in scripts),
   "v1_1_7":sum(k.startswith("validate:v1.1.7") for k in scripts),
   "v1_2":sum(k.startswith("validate:v1.2") for k in scripts),
 },
 "exact_duplicate_blobs_excluding_raw_archives_and_session_history":{
   "groups":len(dups),
   "files_in_groups":sum(len(g) for g in dups),
   "duplicate_bytes_beyond_one_copy":sum((len(g)-1)*g[0]["size"] for g in dups),
   "top15":[{"bytes_each":g[0]["size"],"copies":len(g),"paths":[r["rel"] for r in g[:12]]} for g in dups_sorted[:15]]
 }
}
print(json.dumps(out,ensure_ascii=False,indent=2))
PY`;
const r=await tools.exec_command({cmd,workdir:repo,yield_time_ms:30000,max_output_tokens:20000});
text(r.output);

