#!/usr/bin/env python3
"""Generate S02-P1 read-only repository inventory reports.

The script never reads raw/session-history blob contents.  It consumes the
GitHub recursive tree response, an unquoted `git ls-tree` export, and a
path-only Git history export.  Content reads are restricted to non-raw package
manifests, workflows, validators, and selected large text/code files needed for
maintenance-cost estimates.
"""

from __future__ import annotations

import argparse
import collections
import datetime as dt
import json
import os
import re
import subprocess
from pathlib import Path, PurePosixPath
from typing import Any


TEXT_EXTENSIONS = {
    ".cjs", ".css", ".html", ".js", ".json", ".jsonl", ".jsx", ".md",
    ".mjs", ".py", ".sh", ".sql", ".toml", ".ts", ".tsx", ".txt",
    ".yaml", ".yml",
}
CODE_EXTENSIONS = {
    ".cjs", ".css", ".html", ".js", ".jsx", ".mjs", ".py", ".sh",
    ".sql", ".ts", ".tsx",
}
OWNER_FILENAMES = {
    "AGENTS.md", "README.md", "VERSION", "功能清单.md", "开发记录.md",
    "模型参数文件.md",
}
ALLOWED_CATEGORIES = {"keep", "merge", "delete", "regenerate", "migrate"}
ALLOWED_APPROVALS = {"pending", "approved", "rejected"}
REQUIRED_CANDIDATE_FIELDS = {
    "path", "category", "references", "runtime_dependency",
    "replacement_source", "reason", "restore_method", "batch",
    "validation", "approval",
}


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo", type=Path, required=True)
    parser.add_argument("--ref", default="origin/main")
    parser.add_argument("--github-tree", type=Path, required=True)
    parser.add_argument("--git-tree", type=Path, required=True)
    parser.add_argument("--history", type=Path, required=True)
    parser.add_argument("--out", type=Path, required=True)
    return parser.parse_args()


def run_git(repo: Path, *args: str, text: bool = True) -> str | bytes:
    env = os.environ.copy()
    env["GIT_NO_LAZY_FETCH"] = "1"
    completed = subprocess.run(
        ["git", "-c", "core.quotepath=false", *args],
        cwd=repo,
        env=env,
        check=True,
        capture_output=True,
        text=text,
    )
    return completed.stdout


def is_raw_or_session_path(path: str) -> bool:
    low = "/" + path.lower().strip("/") + "/"
    protected_fragments = (
        "/data/raw/", "/data/raw_archives/", "/data/public_raw/",
        "/raw_archives/", "/public_raw/", "/session_history/",
        "/sessions_history/", "/private_imports/", "/private_exports/",
    )
    return any(fragment in low for fragment in protected_fragments)


def extension(path: str) -> str:
    suffix = PurePosixPath(path).suffix.lower()
    return suffix or "[no extension]"


def top_level(path: str) -> str:
    return path.split("/", 1)[0] if "/" in path else "[root]"


def parse_local_tree(path: Path) -> dict[str, dict[str, Any]]:
    result: dict[str, dict[str, Any]] = {}
    for raw in path.read_bytes().split(b"\0"):
        if not raw:
            continue
        parts = raw.split(b"\t", 3)
        if len(parts) != 4:
            raise ValueError(f"malformed git tree record: {raw[:100]!r}")
        mode, object_type, sha, file_path = (part.decode("utf-8") for part in parts)
        if object_type != "blob":
            continue
        result[file_path] = {"mode": mode, "object_type": object_type, "sha": sha}
    return result


def parse_history(path: Path, current_paths: set[str]) -> dict[str, int]:
    newest: dict[str, int] = {}
    for chunk in path.read_bytes().split(b"\x1e"):
        if not chunk:
            continue
        lines = chunk.splitlines()
        if not lines:
            continue
        try:
            timestamp = int(lines[0].strip())
        except ValueError:
            continue
        for raw_path in lines[1:]:
            if not raw_path:
                continue
            file_path = raw_path.decode("utf-8")
            if file_path in current_paths and file_path not in newest:
                newest[file_path] = timestamp
    return newest


def iso_utc(timestamp: int | None) -> str | None:
    if timestamp is None:
        return None
    return dt.datetime.fromtimestamp(timestamp, tz=dt.timezone.utc).isoformat().replace("+00:00", "Z")


def classify_role(path: str) -> str:
    low = path.lower()
    name = PurePosixPath(path).name
    ext = extension(path)
    if is_raw_or_session_path(path):
        return "raw_or_session_metadata"
    if name in OWNER_FILENAMES:
        return "owner_entry"
    if low.startswith(".github/workflows/") or "/.github/workflows/" in low:
        return "workflow"
    if name == "package.json":
        return "package_manifest"
    if re.search(r"(^|/)(tests?|testdata|fixtures?)(/|$)", low) or name.startswith("test_"):
        return "test_or_fixture"
    if "validate" in name.lower() or "/validators/" in low:
        return "validator"
    if re.search(r"(^|/)(scripts?|tools?)(/|$)", low) and ext in CODE_EXTENSIONS:
        return "script"
    if ext in CODE_EXTENSIONS:
        return "source"
    if ext in {".md", ".txt"} or re.search(r"(^|/)(docs?|handoff)(/|$)", low):
        return "human_document"
    if re.search(r"(^|/)(artifacts?|evidence|logs?|reports?|snapshots?)(/|$)", low):
        return "generated_evidence"
    if "/data/" in low:
        return "data"
    return "other"


def default_protection(path: str, active_projects: set[str]) -> str | None:
    parts = path.split("/")
    name = parts[-1]
    if is_raw_or_session_path(path):
        return "raw_append_only_or_session_history"
    if path.startswith("FINAL_ACCEPTANCE_BUNDLE/cloudflare_compatibility_envelope/"):
        return "current_goal_release_evidence"
    if path.startswith("HANDOFF/"):
        return "current_goal_handoff_pending_reference_audit"
    if path in {"AGENTS.md", "governance/projects.yaml", "governance/project_schema.yaml"}:
        return "root_governance_required"
    if parts[0] in active_projects and len(parts) == 2 and name in OWNER_FILENAMES:
        return "active_project_owner_entry"
    low = path.lower()
    if any(token in low for token in ("wrangler.json", "wrangler.toml", "cloudflare-public/package.json")):
        return "current_deployment_configuration"
    return None


def git_blob_reader(repo: Path, ref: str, content_reads: set[str]):
    cache: dict[str, bytes] = {}

    def read(path: str) -> bytes:
        if is_raw_or_session_path(path):
            raise RuntimeError(f"raw/session content read blocked: {path}")
        if path not in cache:
            cache[path] = run_git(repo, "show", f"{ref}:{path}", text=False)  # type: ignore[assignment]
            content_reads.add(path)
        return cache[path]

    return read


def line_count(data: bytes) -> int:
    if not data:
        return 0
    return data.count(b"\n") + (0 if data.endswith(b"\n") else 1)


def candidate_tags(path: str, role: str) -> list[str]:
    low = path.lower()
    name = PurePosixPath(path).name.lower()
    tags: list[str] = []
    if re.search(r"(^|/)(node_modules|dist|build|coverage|__pycache__|\.pytest_cache|\.cache|\.wrangler)(/|$)", low) or name.endswith(".tsbuildinfo"):
        tags.append("tracked_build_or_cache_output")
    if re.search(r"task[ _-]?pack|taskpack|任务包", low):
        tags.append("historical_taskpack_or_task_bundle")
    if re.search(r"(^|[/_.-])handoff([/_.-]|$)|交接", low):
        tags.append("handoff_record")
    if re.search(r"acceptance|验收", low):
        tags.append("acceptance_record")
    if re.search(r"(^|[/_.-])(stage|phase|review)([/_.-]|[0-9])|阶段|复审", low):
        tags.append("stage_phase_or_review_record")
    if role == "validator":
        tags.append("validator_consolidation_candidate")
    if re.search(r"(^|/)(artifacts?|run_manifests?|evidence|logs?|reports?|snapshots?)(/|$)", low) or "snapshot" in name:
        tags.append("generated_evidence_or_snapshot")
    if re.search(r"(^|/)(archive|archives|backup|backups)(/|$)", low) and not is_raw_or_session_path(path):
        tags.append("historical_archive")
    if extension(path) in {".zip", ".tar", ".gz", ".tgz", ".7z"} and not is_raw_or_session_path(path):
        tags.append("tracked_delivery_archive")
    if role == "human_document" and re.search(r"report|summary|记录|报告|总结", name):
        tags.append("report_or_record_review_candidate")
    return sorted(set(tags))


def category_for(tags: set[str]) -> str:
    if "tracked_build_or_cache_output" in tags:
        return "regenerate"
    if "exact_blob_duplicate" in tags or "validator_consolidation_candidate" in tags or "report_or_record_review_candidate" in tags:
        return "merge"
    return "migrate"


def batch_for(path: str, role: str, tags: set[str]) -> str:
    low = path.lower()
    if "tracked_build_or_cache_output" in tags or "generated_evidence_or_snapshot" in tags:
        return "generated"
    if role == "validator" or role == "test_or_fixture":
        return "validation"
    if low.startswith("governance/") or "/机器治理/" in path or "/governance/" in low:
        return "governance"
    if role in {"human_document", "owner_entry"} or extension(path) in {".md", ".txt"}:
        return "documents"
    return "frontend_scripts"


def main() -> None:
    args = parse_args()
    args.out.mkdir(parents=True, exist_ok=True)
    generated_at = dt.datetime.now(tz=dt.timezone.utc).isoformat().replace("+00:00", "Z")

    github_payload = json.loads(args.github_tree.read_text(encoding="utf-8"))
    if github_payload.get("truncated") is not False:
        raise RuntimeError("GitHub recursive tree is missing or truncated")
    remote_blobs = {
        item["path"]: item
        for item in github_payload["tree"]
        if item.get("type") == "blob"
    }
    local_blobs = parse_local_tree(args.git_tree)
    if set(remote_blobs) != set(local_blobs):
        raise RuntimeError(
            f"GitHub/local path mismatch missing={len(set(remote_blobs)-set(local_blobs))} "
            f"extra={len(set(local_blobs)-set(remote_blobs))}"
        )
    sha_mismatches = [
        path for path in remote_blobs
        if remote_blobs[path]["sha"] != local_blobs[path]["sha"]
    ]
    if sha_mismatches:
        raise RuntimeError(f"GitHub/local blob mismatch count={len(sha_mismatches)}")

    source_commit = str(run_git(args.repo, "rev-parse", args.ref)).strip()
    source_root_tree = str(run_git(args.repo, "rev-parse", f"{args.ref}^{{tree}}")).strip()
    current_paths = set(remote_blobs)
    modified = parse_history(args.history, current_paths)
    history_missing = sorted(current_paths - set(modified))

    content_reads: set[str] = set()
    read_blob = git_blob_reader(args.repo, args.ref, content_reads)
    projects_text = read_blob("governance/projects.yaml").decode("utf-8")
    active_projects = set(re.findall(r"^\s*pat[REDACTED_LOCAL_PATH]"']?([^\"'\n#]+)", projects_text, flags=re.MULTILINE))
    active_projects = {path.strip().rstrip("/") for path in active_projects if path.strip()}

    roles = {path: classify_role(path) for path in current_paths}
    protections = {path: default_protection(path, active_projects) for path in current_paths}

    manifest_paths = sorted(path for path in current_paths if PurePosixPath(path).name == "package.json")
    workflow_paths = sorted(
        path for path in current_paths
        if roles[path] == "workflow" and extension(path) in {".yaml", ".yml"}
    )
    reference_map: dict[str, list[str]] = collections.defaultdict(list)
    manifest_scripts: list[dict[str, str]] = []
    reference_texts: dict[str, str] = {}
    for path in manifest_paths:
        raw = read_blob(path)
        text = raw.decode("utf-8", errors="replace")
        reference_texts[path] = text
        try:
            package = json.loads(text)
        except json.JSONDecodeError:
            continue
        scripts = package.get("scripts", {})
        if isinstance(scripts, dict):
            for name, command in scripts.items():
                if isinstance(command, str):
                    manifest_scripts.append({"manifest": path, "name": str(name), "command": command})
    for path in workflow_paths:
        reference_texts[path] = read_blob(path).decode("utf-8", errors="replace")

    script_paths = sorted(path for path in current_paths if roles[path] in {"script", "validator"})
    basename_counts = collections.Counter(PurePosixPath(path).name for path in script_paths)
    for script_path in script_paths:
        basename = PurePosixPath(script_path).name
        for source_path, text in reference_texts.items():
            if script_path in text or (basename_counts[basename] == 1 and basename in text):
                reference_map[script_path].append(source_path)

    duplicate_groups = {
        sha: sorted(paths)
        for sha, paths in collections.defaultdict(list, {
            sha: [] for sha in []
        }).items()
    }
    by_sha: dict[str, list[str]] = collections.defaultdict(list)
    for path, item in remote_blobs.items():
        if not is_raw_or_session_path(path):
            by_sha[item["sha"]].append(path)
    duplicate_groups = {sha: sorted(paths) for sha, paths in by_sha.items() if len(paths) > 1}
    duplicate_membership = {
        path: sha for sha, paths in duplicate_groups.items() for path in paths
    }

    candidate_data: dict[str, dict[str, Any]] = {}
    protected_candidate_counts: collections.Counter[str] = collections.Counter()
    for path in sorted(current_paths):
        role = roles[path]
        tags = set(candidate_tags(path, role))
        if path in duplicate_membership:
            tags.add("exact_blob_duplicate")
        if not tags:
            continue
        protection = protections[path]
        if protection:
            protected_candidate_counts[protection] += 1
            continue
        refs = [f"P1:path-classification:{tag}" for tag in sorted(tags)]
        if path in duplicate_membership:
            refs.append(f"P1:exact-blob-duplicate:{duplicate_membership[path]}")
        if modified.get(path):
            refs.append(f"P1:last-commit:{iso_utc(modified[path])}")
        manifest_refs = sorted(set(reference_map.get(path, [])))
        refs.extend(f"P1:manifest-or-workflow:{ref}" for ref in manifest_refs)
        refs.append("P2_REQUIRED:content-workflow-runtime-reference-audit")
        if manifest_refs:
            runtime_dependency = (
                f"PRESENT:{len(manifest_refs)} package/workflow reference(s); "
                "dynamic and runtime references remain pending S02-P2"
            )
        else:
            runtime_dependency = "UNKNOWN_PENDING_S02_P2"
        if path in duplicate_membership:
            replacement = (
                f"EXACT_BLOB_GROUP:{duplicate_membership[path]}; canonical path pending S02-P2"
            )
        elif "validator_consolidation_candidate" in tags:
            replacement = "future validation profiles fast/sync/ui/release; exact replacement pending S02-P2"
        elif "tracked_build_or_cache_output" in tags:
            replacement = "source-and-regenerator contract pending S02-P2"
        else:
            replacement = "UNKNOWN_PENDING_S02_P2"
        candidate_data[path] = {
            "path": path,
            "category": category_for(tags),
            "references": refs,
            "runtime_dependency": runtime_dependency,
            "replacement_source": replacement,
            "reason": "; ".join(sorted(tags)) + "; provisional metadata-only classification",
            "restore_method": f"git restore --source={source_commit} -- '{path}'",
            "batch": batch_for(path, role, tags),
            "validation": [
                "S02-P2 exact static and dynamic reference search",
                "S02-P2 runtime/import/package/workflow dependency check",
                "S02-P2 replacement or regeneration proof",
                "S02-P3 user approval before any mutation",
            ],
            "approval": "pending",
        }

    for item in candidate_data.values():
        if set(item) != REQUIRED_CANDIDATE_FIELDS:
            raise RuntimeError(f"candidate schema mismatch: {item['path']}")
        if item["category"] not in ALLOWED_CATEGORIES:
            raise RuntimeError(f"invalid category: {item['path']}")
        if item["approval"] not in ALLOWED_APPROVALS:
            raise RuntimeError(f"invalid approval: {item['path']}")
        if item["category"] == "delete":
            raise RuntimeError(f"P1 must not approve delete classification: {item['path']}")

    large_docs = sorted(
        (
            (path, int(remote_blobs[path].get("size", 0)))
            for path in current_paths
            if not is_raw_or_session_path(path)
            and roles[path] in {"human_document", "owner_entry"}
            and extension(path) in {".md", ".txt"}
        ),
        key=lambda pair: (-pair[1], pair[0]),
    )[:40]
    large_code = sorted(
        (
            (path, int(remote_blobs[path].get("size", 0)))
            for path in current_paths
            if not is_raw_or_session_path(path)
            and roles[path] in {"source", "script", "validator"}
            and extension(path) in CODE_EXTENSIONS
        ),
        key=lambda pair: (-pair[1], pair[0]),
    )[:60]
    validator_paths = sorted(path for path in current_paths if roles[path] == "validator" and not is_raw_or_session_path(path))
    measured_paths = sorted(set(path for path, _ in large_docs + large_code) | set(validator_paths))
    measured_lines: dict[str, int] = {}
    for path in measured_paths:
        measured_lines[path] = line_count(read_blob(path))

    single_use_scripts = [
        path for path in script_paths
        if roles[path] == "script"
        and not reference_map.get(path)
        and basename_counts[PurePosixPath(path).name] == 1
        and re.search(r"(^|/)scripts?(/|$)", path.lower())
        and not protections[path]
    ]
    single_use_scripts.sort(key=lambda path: (-int(remote_blobs[path].get("size", 0)), path))

    files: list[dict[str, Any]] = []
    for path in sorted(current_paths):
        item = remote_blobs[path]
        raw_metadata_only = is_raw_or_session_path(path)
        manifest_refs = sorted(set(reference_map.get(path, [])))
        role = roles[path]
        relation = role
        if top_level(path) in active_projects:
            relation = f"active_project:{top_level(path)}:{role}"
        elif path.startswith("governance/") or path == "AGENTS.md":
            relation = f"root_governance:{role}"
        files.append({
            "path": path,
            "blob_sha": item["sha"],
            "bytes": int(item.get("size", 0)),
            "git_last_modified_unix": modified.get(path),
            "git_last_modified_utc": iso_utc(modified.get(path)),
            "top_level": top_level(path),
            "project": top_level(path) if top_level(path) in active_projects else "ROOT_OR_UNREGISTERED",
            "extension": extension(path),
            "file_class": role,
            "parent_dir": str(PurePosixPath(path).parent),
            "reference_relation": relation,
            "manifest_or_workflow_references": manifest_refs,
            "reference_evidence_level": "path_and_manifest_only_p2_required",
            "candidate_tags": candidate_tags(path, role) + (["exact_blob_duplicate"] if path in duplicate_membership else []),
            "protected_reason": protections[path],
            "raw_or_session_metadata_only": raw_metadata_only,
            "content_read": path in content_reads,
        })

    top_stats: dict[str, dict[str, int]] = collections.defaultdict(lambda: {"files": 0, "bytes": 0})
    ext_stats: dict[str, dict[str, int]] = collections.defaultdict(lambda: {"files": 0, "bytes": 0})
    role_stats: dict[str, dict[str, int]] = collections.defaultdict(lambda: {"files": 0, "bytes": 0})
    raw_stats = {"files": 0, "bytes": 0}
    for record in files:
        for stats, key in ((top_stats, record["top_level"]), (ext_stats, record["extension"]), (role_stats, record["file_class"])):
            stats[key]["files"] += 1
            stats[key]["bytes"] += record["bytes"]
        if record["raw_or_session_metadata_only"]:
            raw_stats["files"] += 1
            raw_stats["bytes"] += record["bytes"]

    inventory = {
        "schema_version": "s02-p1.repo-inventory.v1",
        "stage": "S02",
        "phase": "P1",
        "task": "S02-P1-T1",
        "generated_at_utc": generated_at,
        "source": {
            "repository": str(args.repo),
            "ref": args.ref,
            "commit": source_commit,
            "root_tree": source_root_tree,
            "github_api_commit": github_payload.get("sha"),
            "github_api_truncated": github_payload.get("truncated"),
            "local_remote_path_sha_match": True,
        },
        "content_policy": {
            "raw_or_session_content_reads": 0,
            "raw_or_session_metadata_only": True,
            "nonraw_content_read_count": len(content_reads),
            "nonraw_content_read_paths": sorted(content_reads),
            "note": "Only non-raw manifests, workflows, validators, and selected large text/code blobs were read for P1 cost estimates.",
        },
        "summary": {
            "tracked_blob_count": len(files),
            "tracked_blob_bytes": sum(record["bytes"] for record in files),
            "history_modified_time_coverage": len(files) - len(history_missing),
            "history_missing_count": len(history_missing),
            "history_missing_paths": history_missing,
            "raw_or_session_metadata": raw_stats,
            "active_projects": sorted(active_projects),
            "by_top_level": dict(sorted(top_stats.items(), key=lambda pair: (-pair[1]["bytes"], pair[0]))),
            "by_extension": dict(sorted(ext_stats.items(), key=lambda pair: (-pair[1]["files"], pair[0]))),
            "by_file_class": dict(sorted(role_stats.items(), key=lambda pair: (-pair[1]["files"], pair[0]))),
            "exact_nonraw_duplicate_groups": len(duplicate_groups),
            "exact_nonraw_duplicate_members": sum(len(paths) for paths in duplicate_groups.values()),
            "provisional_cleanup_candidate_count": len(candidate_data),
        },
        "files": files,
    }

    cleanup = {
        "schema_version": "s02-p1.cleanup-candidates.v1",
        "stage": "S02",
        "phase": "P1",
        "task": "S02-P1-T2",
        "generated_at_utc": generated_at,
        "source_commit": source_commit,
        "status": "PROVISIONAL_METADATA_ONLY_PENDING_S02_P2_AND_USER_APPROVAL",
        "mutation_performed": False,
        "policy": {
            "allowed_categories": sorted(ALLOWED_CATEGORIES),
            "approval_values": sorted(ALLOWED_APPROVALS),
            "p1_delete_classifications": 0,
            "all_candidates_pending": True,
            "raw_or_session_candidates": 0,
            "protected_principle": "Active source, deployment config, current release evidence, raw append-only archives, and owner entries are preserved by default.",
        },
        "summary": {
            "candidate_count": len(candidate_data),
            "by_category": dict(collections.Counter(item["category"] for item in candidate_data.values())),
            "by_batch": dict(collections.Counter(item["batch"] for item in candidate_data.values())),
            "protected_matches_excluded": dict(protected_candidate_counts),
        },
        "candidates": [candidate_data[path] for path in sorted(candidate_data)],
    }

    command_groups: dict[str, list[str]] = collections.defaultdict(list)
    for item in manifest_scripts:
        command_groups[item["command"]].append(f"{item['manifest']}#scripts.{item['name']}")
    repeated_commands = {
        command: refs for command, refs in command_groups.items() if len(refs) > 1
    }
    validator_stats: dict[str, dict[str, int]] = collections.defaultdict(lambda: {"files": 0, "bytes": 0, "measured_lines": 0})
    for path in validator_paths:
        key = top_level(path)
        validator_stats[key]["files"] += 1
        validator_stats[key]["bytes"] += int(remote_blobs[path].get("size", 0))
        validator_stats[key]["measured_lines"] += measured_lines.get(path, 0)
    duplicate_redundant_bytes = sum(
        int(remote_blobs[paths[0]].get("size", 0)) * (len(paths) - 1)
        for paths in duplicate_groups.values()
    )

    def table_rows(pairs: list[tuple[str, int]], limit: int, include_lines: bool = False) -> list[str]:
        rows = []
        for path, size in pairs[:limit]:
            line_value = str(measured_lines.get(path, "not measured")) if include_lines else "-"
            rows.append(f"| `{path}` | {size:,} | {line_value} |")
        return rows

    top_project_rows = [
        f"| `{name}` | {stats['files']:,} | {stats['bytes']:,} | {stats['bytes']/max(1, sum(record['bytes'] for record in files))*100:.2f}% |"
        for name, stats in list(sorted(top_stats.items(), key=lambda pair: (-pair[1]["bytes"], pair[0])))[:15]
    ]
    validator_rows = [
        f"| `{name}` | {stats['files']:,} | {stats['bytes']:,} | {stats['measured_lines']:,} |"
        for name, stats in sorted(validator_stats.items(), key=lambda pair: (-pair[1]["files"], pair[0]))
    ]
    single_use_rows = [
        f"| `{path}` | {int(remote_blobs[path].get('size', 0)):,} | {iso_utc(modified.get(path)) or 'unknown'} |"
        for path in single_use_scripts[:30]
    ]
    duplicate_rows = []
    for sha, paths in sorted(
        duplicate_groups.items(),
        key=lambda pair: (-int(remote_blobs[pair[1][0]].get("size", 0)) * (len(pair[1]) - 1), pair[0]),
    )[:20]:
        size = int(remote_blobs[paths[0]].get("size", 0))
        duplicate_rows.append(f"| `{sha[:12]}` | {len(paths)} | {size * (len(paths)-1):,} | `{paths[0]}` |")

    total_bytes = sum(record["bytes"] for record in files)
    md_bytes = ext_stats.get(".md", {"bytes": 0})["bytes"]
    hotspot_lines = [
        "# S02-P1 Maintenance Hotspots",
        "",
        f"Generated: `{generated_at}`  ",
        f"Source: `{args.ref}` / `{source_commit}` / tree `{source_root_tree}`  ",
        "Boundary: read-only P1 classification. No deletion, move, merge, deployment, branch, PR, or repository source write was performed.",
        "",
        "## Executive findings",
        "",
        f"- Inventory covers **{len(files):,} tracked blobs / {total_bytes:,} bytes**; GitHub and local `origin/main` path+SHA tuples match exactly and the API tree is not truncated.",
        f"- Raw/session material accounts for **{raw_stats['files']:,} files / {raw_stats['bytes']:,} bytes ({raw_stats['bytes']/max(1,total_bytes)*100:.2f}%)**. It was classified from paths and metadata only; raw/session content reads are **0**.",
        f"- Markdown alone is **{ext_stats.get('.md', {}).get('files', 0):,} files / {md_bytes:,} bytes**, roughly **{md_bytes/4:,.0f} tokens** if loaded naively. Context must stay owner-entry and task scoped.",
        f"- P1 exposes **{len(candidate_data):,} provisional candidates**, all `approval=pending`; **0** are classified for immediate deletion and **0** raw/session paths are candidates.",
        f"- Non-raw exact duplicates: **{len(duplicate_groups):,} groups / {sum(len(v) for v in duplicate_groups.values()):,} members**, theoretical redundant storage **{duplicate_redundant_bytes:,} bytes**. Equality alone is not deletion proof.",
        f"- Validators: **{len(validator_paths):,} tracked files**. Package manifests expose **{len(manifest_scripts):,} scripts**, including **{sum(1 for item in manifest_scripts if item['name'].lower().startswith('validate')):,} validate-prefixed scripts** and **{len(repeated_commands):,} exact repeated command strings**.",
        f"- Metadata-only single-use-script screen found **{len(single_use_scripts):,} paths** with a unique basename and no package/workflow textual reference. These are hotspots, not deletion approvals; imports, docs, shell indirection, runtime discovery, and operator use remain S02-P2 work.",
        "",
        "## Repository storage concentration",
        "",
        "| Top level | Files | Bytes | Share |",
        "|---|---:|---:|---:|",
        *top_project_rows,
        "",
        "## Largest human-facing documents",
        "",
        "These files create review and context cost. Lines are measured from non-raw blobs only.",
        "",
        "| Path | Bytes | Lines |",
        "|---|---:|---:|",
        *table_rows(large_docs, 25, include_lines=True),
        "",
        "## Giant code and entrypoint hotspots",
        "",
        "| Path | Bytes | Lines |",
        "|---|---:|---:|",
        *table_rows(large_code, 30, include_lines=True),
        "",
        "## Validator surface",
        "",
        "| Top level | Validator files | Bytes | Measured lines |",
        "|---|---:|---:|---:|",
        *validator_rows,
        "",
        "Recommended P2 question: which validators are runtime gates, which duplicate the same assertion, and which can be represented by four canonical profiles (`fast`, `sync`, `ui`, `release`) without weakening coverage?",
        "",
        "## Package-script duplication",
        "",
        f"- Package manifests: **{len(manifest_paths)}**.",
        f"- Declared scripts: **{len(manifest_scripts)}**.",
        f"- Exact repeated command strings: **{len(repeated_commands)}**.",
        "- Exact command equality is a consolidation signal only; working directory, environment, and package ownership still matter.",
        "",
        "## Single-use script screen",
        "",
        "| Path | Bytes | Last modified in Git |",
        "|---|---:|---|",
        *(single_use_rows or ["| _none_ | 0 | - |"]),
        "",
        "## Largest exact duplicate groups (non-raw)",
        "",
        "| Blob SHA | Members | Theoretical redundant bytes | Example member |",
        "|---|---:|---:|---|",
        *(duplicate_rows or ["| _none_ | 0 | 0 | - |"]),
        "",
        "## False-positive and protection controls",
        "",
        "- Raw append-only archives and session-history material: metadata only; never candidates.",
        "- Active project owner entries, current deployment configuration, the current Cloudflare compatibility acceptance bundle, root governance files, and current handoff: excluded from candidate mutation until exact references and ownership are known.",
        "- Exact duplicates, old-looking names, age, size, and a missing package/workflow reference are signals—not proof of safe removal.",
        "- Every cleanup candidate requires S02-P2 static/dynamic/runtime reference proof, a replacement or regeneration source, a restore method, batch validation, and S02-P3 user approval.",
        "",
        "## Required next phase checks (not executed in this run)",
        "",
        "1. Resolve imports, shell indirection, package scripts, workflows, docs, launchers, tests, and dynamic file discovery for every proposed batch.",
        "2. Identify canonical replacements for duplicate TaskPacks, validators, reports, snapshots, and package commands.",
