#!/usr/bin/env python3
"""Generate S02-P2 read-only reference, disposition, and history evidence.

The script scans only non-raw reference-bearing text at a pinned Git commit.
Worktree content is accepted only when its Git blob SHA matches the pinned
tree; missing text is fetched from the public pinned raw URL and verified.
Raw/session content is never opened, cached, indexed, or emitted.
"""

from __future__ import annotations

import argparse
import collections
import concurrent.futures
import csv
import datetime as dt
import hashlib
import json
import os
import posixpath
import re
import sqlite3
import threading
import time
import urllib.parse
from collections import deque
from pathlib import Path, PurePosixPath
from typing import Any, Iterable

import requests


TEXT_EXTENSIONS = {
    ".c", ".cjs", ".conf", ".cfg", ".cpp", ".css", ".csv", ".diff",
    ".env.example", ".go", ".h", ".hpp", ".html", ".ini", ".java",
    ".js", ".json", ".json5", ".jsonc", ".jsonl", ".jsx", ".kt",
    ".lock", ".md", ".mjs", ".patch", ".plist", ".properties", ".py",
    ".rb", ".rs", ".sh", ".sql", ".svg", ".toml", ".ts", ".tsv",
    ".tsx", ".txt", ".vue", ".xml", ".yaml", ".yml",
}
TEXT_BASENAMES = {
    ".editorconfig", ".gitignore", ".npmrc", "Dockerfile", "Gemfile",
    "Makefile", "Procfile", "requirements.txt",
}
CODE_EXTENSIONS = {
    ".c", ".cjs", ".cpp", ".go", ".h", ".hpp", ".html", ".java",
    ".js", ".jsx", ".kt", ".mjs", ".py", ".rb", ".rs", ".sh",
    ".sql", ".ts", ".tsx", ".vue",
}
DISPOSITIONS = {"keep", "merge", "delete", "regenerate", "migrate"}
ACTIVE_PROJECT_FALLBACK = {
    "Alpha", "EEI", "FIFA", "KMFA", "KM_IDSystem", "MetaDatabase",
    "OpenAIDatabase", "PFI", "QBVS", "Serenity-Alipay", "WDA",
    "arxiv-daily-push", "whkmSalary",
}
PATH_CHARS = set("_./-:@")
STRONG_KINDS = {"full_path", "project_relative", "markdown_resolved", "extensionless_import", "p1_manifest"}


class AhoCorasick:
    def __init__(self, patterns: Iterable[str]):
        self.next: list[dict[str, int]] = [{}]
        self.fail: list[int] = [0]
        self.output: list[list[str]] = [[]]
        for pattern in patterns:
            state = 0
            for char in pattern:
                state = self.next[state].setdefault(char, self._new_state())
            self.output[state].append(pattern)
        queue: deque[int] = deque()
        for state in self.next[0].values():
            queue.append(state)
        while queue:
            parent = queue.popleft()
            for char, child in self.next[parent].items():
                queue.append(child)
                fallback = self.fail[parent]
                while fallback and char not in self.next[fallback]:
                    fallback = self.fail[fallback]
                self.fail[child] = self.next[fallback].get(char, 0)
                self.output[child].extend(self.output[self.fail[child]])

    def _new_state(self) -> int:
        self.next.append({})
        self.fail.append(0)
        self.output.append([])
        return len(self.next) - 1

    def find(self, text: str):
        state = 0
        for index, char in enumerate(text):
            while state and char not in self.next[state]:
                state = self.fail[state]
            state = self.next[state].get(char, 0)
            for pattern in self.output[state]:
                yield index - len(pattern) + 1, index + 1, pattern


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo", type=Path, required=True)
    parser.add_argument("--commit", required=True)
    parser.add_argument("--github-repo", default="LinzeColin/CodexProject")
    parser.add_argument("--inventory", type=Path, required=True)
    parser.add_argument("--candidates", type=Path, required=True)
    parser.add_argument("--github-tree", type=Path, required=True)
    parser.add_argument("--taskpack", type=Path, required=True)
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--workers", type=int, default=16)
    parser.add_argument("--max-text-bytes", type=int, default=20_000_000)
    return parser.parse_args()


def git_blob_sha(data: bytes) -> str:
    return hashlib.sha1(f"blob {len(data)}\0".encode("ascii") + data).hexdigest()


def is_reference_text(record: dict[str, Any], max_bytes: int) -> bool:
    if record["raw_or_session_metadata_only"]:
        return False
    if int(record["bytes"]) > max_bytes:
        return False
    path = record["path"]
    suffixes = PurePosixPath(path).suffixes
    compound = "".join(suffixes[-2:]).lower() if len(suffixes) >= 2 else ""
    extension = PurePosixPath(path).suffix.lower()
    return (
        extension in TEXT_EXTENSIONS
        or compound in TEXT_EXTENSIONS
        or PurePosixPath(path).name in TEXT_BASENAMES
        or record["file_class"] in {"workflow", "package_manifest"}
    )


def classify_source(path: str, record: dict[str, Any] | None) -> str:
    low = path.lower()
    if path.startswith("TASKPACK::"):
        return "taskpack"
    if record is None:
        return "external"
    if record["file_class"] == "workflow" or "/.github/workflows/" in f"/{low}":
        return "workflow"
    if record["file_class"] == "package_manifest":
        return "package"
    if "wrangler" in low or "/deploy" in low or "cloudflare" in low:
        return "deploy"
    if record["file_class"] == "test_or_fixture" or re.search(r"(^|/)tests?(/|$)", low):
        return "test"
    if "/config/" in f"/{low}" or record["extension"] in {".yaml", ".yml", ".toml", ".ini", ".jsonc"}:
        return "config"
    if record["file_class"] in {"human_document", "owner_entry"}:
        return "documentation"
    if record["file_class"] in {"data", "generated_evidence"} or "/metadata/" in f"/{low}":
        return "data_manifest"
    return "code"


def is_boundary(text: str, start: int, end: int) -> bool:
    before = text[start - 1] if start > 0 else ""
    after = text[end] if end < len(text) else ""

    def path_char(char: str) -> bool:
        return bool(char) and (char.isalnum() or char in PATH_CHARS)

    return not path_char(before) and not path_char(after)


def normalize_link(source: str, link: str) -> str | None:
    link = urllib.parse.unquote(link.strip().strip("<>\"'"))
    if not link or link.startswith("#") or re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", link):
        return None
    link = link.split("#", 1)[0].split("?", 1)[0]
    if not link:
        return None
    if link.startswith("/"):
        return posixpath.normpath(link.lstrip("/"))
    return posixpath.normpath(posixpath.join(posixpath.dirname(source), link))


class ContentCache:
    def __init__(self, path: Path):
        self.path = path
        self.connection = sqlite3.connect(path)
        self.connection.execute(
            "CREATE TABLE IF NOT EXISTS blobs (sha TEXT PRIMARY KEY, content BLOB NOT NULL, source TEXT NOT NULL, bytes INTEGER NOT NULL)"
        )
        self.connection.commit()

    def get(self, sha: str) -> tuple[bytes, str] | None:
        row = self.connection.execute("SELECT content, source FROM blobs WHERE sha = ?", (sha,)).fetchone()
        if row is None:
            return None
        content = bytes(row[0])
        if git_blob_sha(content) != sha:
            raise RuntimeError(f"cache SHA mismatch: {sha}")
        return content, str(row[1])

    def put_many(self, values: list[tuple[str, bytes, str]]) -> None:
        self.connection.executemany(
            "INSERT OR REPLACE INTO blobs(sha, content, source, bytes) VALUES (?, ?, ?, ?)",
            [(sha, content, source, len(content)) for sha, content, source in values],
        )
        self.connection.commit()

    def close(self) -> None:
        self.connection.close()


_thread_local = threading.local()


def fetch_remote(github_repo: str, commit: str, path: str, expected_sha: str) -> tuple[str, bytes, str, str | None]:
    encoded_path = urllib.parse.quote(path, safe="/")
    url = f"http[REDACTED_LOCAL_PATH]"
    if not hasattr(_thread_local, "session"):
        _thread_local.session = requests.Session()
        _thread_local.session.headers.update({"User-Agent": "Codex-S02-P2-read-only-reference-audit"})
    last_error = ""
    for attempt in range(3):
        try:
            response = _thread_local.session.get(url, timeout=(10, 45))
            response.raise_for_status()
            content = response.content
            actual_sha = git_blob_sha(content)
            if actual_sha != expected_sha:
                raise RuntimeError(f"SHA mismatch expected={expected_sha} actual={actual_sha}")
            return path, content, "github_raw_pinned_commit", None
        except Exception as error:  # network and verification failure are both fail-closed
            last_error = f"{type(error).__name__}:{error}"
            time.sleep(0.4 * (attempt + 1))
    return path, b"", "failed", last_error


def choose_canonical(paths: list[str], records: dict[str, dict[str, Any]], candidate_set: set[str]) -> str:
    def score(path: str):
        record = records[path]
        noncandidate = 0 if path not in candidate_set else 1
        protected = 0 if record.get("protected_reason") else 1
        latest = 0 if "latest" in path.lower() else 1
        timestamp = -(int(record.get("git_last_modified_unix") or 0))
        return (protected, noncandidate, latest, timestamp, len(path), path)

    return min(paths, key=score)


def project_scope(path: str, active_projects: set[str]) -> str:
    top = path.split("/", 1)[0]
    if top == "OpenAIDatabase":
        return "openaidatabase"
    if top in active_projects:
        return "other_active_project"
    return "shared_repo"


def replacement_for(
    path: str,
    record: dict[str, Any],
    candidate: dict[str, Any],
    scope: str,
    canonical: str | None,
    taskpack: Path,
) -> tuple[str, str, str, str]:
    """Return disposition, reason, replacement, replacement status."""
    low = path.lower()
    role = record["file_class"]
    tags = set(record.get("candidate_tags") or [])

    if record.get("protected_reason") or record.get("raw_or_session_metadata_only"):
        return "keep", "protected current/raw/owner surface", f"SELF_CURRENT_TRUTH:{path}", "SELF"
    if scope == "other_active_project":
        return "keep", "other active project owner/runtime is outside OpenAIDatabase cleanup authority", f"SELF_CURRENT_TRUTH:{path}", "SELF"

    if scope == "openaidatabase":
        if role == "validator":
            return (
                "merge",
