        if path.startswith("OpenAIDatabase/data/derived/") or path.startswith("OpenAIDatabase/data/processed/") or path.startswith("OpenAIDatabase/data/run_logs/") or path.startswith("OpenAIDatabase/data/memory/"):
            if canonical and canonical != path:
                return "regenerate", "derived/run artifact has an exact canonical peer; preserve run semantics until P3", canonical, "EXACT_BLOB_EXISTS"
            return "keep", "derived/runtime value or regeneration contract is not fully proven", f"SELF_CURRENT_TRUTH:{path}", "SELF"
