            return "migrate", "historical handoff/archive/package is recoverable from Git history", f"GIT_HISTORY:{path}", "GIT_HISTORY"
        if canonical and canonical != path and role in {"human_document", "generated_evidence", "other", "data"}:
            return "merge", "exact duplicate should converge on one current truth after reference rewrite", canonical, "EXACT_BLOB_EXISTS"
        if "report_or_record_review_candidate" in tags:
            return "merge", "repeated report/record should consolidate into the owner entry", "OpenAIDatabase/开发记录.md", "EXISTS"
        return "keep", "current runtime/reference role is not disproven", f"SELF_CURRENT_TRUTH:{path}", "SELF"

