def main() -> None:
    args = parse_args()
    args.out.mkdir(parents=True, exist_ok=True)
    generated_at = dt.datetime.now(tz=dt.timezone.utc).isoformat().replace("+00:00", "Z")

    inventory = json.loads(args.inventory.read_text(encoding="utf-8"))
    cleanup = json.loads(args.candidates.read_text(encoding="utf-8"))
    github_tree = json.loads(args.github_tree.read_text(encoding="utf-8"))
    if inventory["source"]["commit"] != args.commit or cleanup["source_commit"] != args.commit:
        raise RuntimeError("P1 artifacts do not match requested commit")
    if github_tree.get("truncated") is not False:
        raise RuntimeError("GitHub tree is truncated")

    records = {record["path"]: record for record in inventory["files"]}
    candidates = {item["path"]: item for item in cleanup["candidates"]}
    candidate_set = set(candidates)
    if len(records) != 7_732 or len(candidates) != 3_737:
        raise RuntimeError(f"unexpected P1 coverage files={len(records)} candidates={len(candidates)}")
    if any(records[path]["raw_or_session_metadata_only"] for path in candidates):
        raise RuntimeError("raw-like path leaked into P1 candidates")

    active_projects = set(inventory["summary"].get("active_projects") or ACTIVE_PROJECT_FALLBACK)
    strict_raw_paths = {path for path, record in records.items() if record["raw_append_only_or_session_history"]}
    raw_like_paths = {path for path, record in records.items() if record["raw_or_session_metadata_only"]}
    corpus_paths = sorted(path for path, record in records.items() if is_reference_text(record, args.max_text_bytes))
    oversized_text = sorted(
        path for path, record in records.items()
        if not record["raw_or_session_metadata_only"]
        and int(record["bytes"]) > args.max_text_bytes
        and (PurePosixPath(path).suffix.lower() in TEXT_EXTENSIONS or record["file_class"] in {"workflow", "package_manifest"})
    )

    cache = ContentCache(args.out / "corpus_cache.sqlite")
    contents: dict[str, bytes] = {}
    content_sources: dict[str, str] = {}
    missing_remote: list[tuple[str, str]] = []
    cache_inserts: list[tuple[str, bytes, str]] = []

    for path in corpus_paths:
        sha = records[path]["blob_sha"]
        cached = cache.get(sha)
        if cached is not None:
            contents[path], content_sources[path] = cached[0], "cache_verified"
            continue
        local_path = args.repo / path
        if local_path.is_file():
            data = local_path.read_bytes()
            if git_blob_sha(data) == sha:
                contents[path] = data
                content_sources[path] = "worktree_sha_verified"
                cache_inserts.append((sha, data, "worktree_sha_verified"))
                continue
        missing_remote.append((path, sha))

    if cache_inserts:
        cache.put_many(cache_inserts)
    print(json.dumps({
        "event": "corpus_plan",
        "reference_text_paths": len(corpus_paths),
        "from_cache_or_worktree": len(contents),
        "remote_required": len(missing_remote),
        "oversized_text_skipped": len(oversized_text),
        "strict_raw_skipped": len(strict_raw_paths),
        "raw_like_control_skipped": len(raw_like_paths - strict_raw_paths),
    }, ensure_ascii=False))

    failures: dict[str, str] = {}
    fetched_values: list[tuple[str, bytes, str]] = []
    if missing_remote:
        with concurrent.futures.ThreadPoolExecutor(max_workers=args.workers) as executor:
            futures = {
                executor.submit(fetch_remote, args.github_repo, args.commit, path, sha): (path, sha)
                for path, sha in missing_remote
            }
            completed = 0
            for future in concurrent.futures.as_completed(futures):
                path, expected_sha = futures[future]
                try:
                    returned_path, data, source, error = future.result()
                except Exception as error_obj:
                    failures[path] = f"{type(error_obj).__name__}:{error_obj}"
                    continue
                if returned_path != path or error:
                    failures[path] = error or "returned path mismatch"
                    continue
                contents[path] = data
                content_sources[path] = source
                fetched_values.append((expected_sha, data, source))
                completed += 1
                if completed % 250 == 0:
                    print(json.dumps({"event": "remote_progress", "completed": completed, "required": len(missing_remote)}))
        if fetched_values:
            cache.put_many(fetched_values)
    cache.close()

    # Drop accidental binary detections from the searchable corpus without emitting content.
    binary_detected = sorted(path for path, data in contents.items() if b"\0" in data[:8192])
    for path in binary_detected:
        del contents[path]
        content_sources.pop(path, None)

    taskpack_contents: dict[str, bytes] = {}
    for path in sorted(args.taskpack.rglob("*")):
        if not path.is_file() or path.stat().st_size > args.max_text_bytes:
            continue
        if path.suffix.lower() not in TEXT_EXTENSIONS and path.name not in TEXT_BASENAMES:
            continue
        data = path.read_bytes()
        if b"\0" in data[:8192]:
            continue
        taskpack_contents[f"TASKPACK::{path.relative_to(args.taskpack).as_posix()}"] = data

    if failures:
        print(json.dumps({"event": "corpus_failures", "count": len(failures), "examples": dict(list(sorted(failures.items()))[:10])}, ensure_ascii=False))

    # Build exact duplicate/canonical mappings from metadata only.
    sha_groups: dict[str, list[str]] = collections.defaultdict(list)
    for path, record in records.items():
        if not record["raw_append_only_or_session_history"] and int(record["bytes"]) > 0:
            sha_groups[record["blob_sha"]].append(path)
    duplicate_groups = {sha: sorted(paths) for sha, paths in sha_groups.items() if len(paths) > 1}
    canonical_by_sha = {
        sha: choose_canonical(paths, records, candidate_set) for sha, paths in duplicate_groups.items()
    }

    basename_counts = collections.Counter(PurePosixPath(path).name for path in records)
    pattern_map: dict[str, list[tuple[str, str]]] = collections.defaultdict(list)

    def add_pattern(pattern: str, target: str, kind: str) -> None:
        pattern = pattern.replace("\\", "/")
        if len(pattern) >= 4:
            value = (target, kind)
            if value not in pattern_map[pattern]:
                pattern_map[pattern].append(value)

    for path in sorted(candidates):
        add_pattern(path, path, "full_path")
        if "/" in path:
            relative = path.split("/", 1)[1]
            add_pattern(relative, path, "project_relative")
        basename = PurePosixPath(path).name
        if basename_counts[basename] == 1 and len(basename) >= 6:
            add_pattern(basename, path, "unique_basename")
        suffix = PurePosixPath(path).suffix.lower()
        if suffix in CODE_EXTENSIONS:
            extensionless = path[: -len(suffix)]
            add_pattern(extensionless, path, "extensionless_import")
            if "/" in extensionless:
                add_pattern(extensionless.split("/", 1)[1], path, "extensionless_import")

    automaton = AhoCorasick(pattern_map)
    references: dict[str, dict[str, set[str]]] = collections.defaultdict(lambda: collections.defaultdict(set))

    # Preserve P1 package/workflow evidence as an independent source.
    for path, record in records.items():
        if path not in candidates:
            continue
        for source in record.get("manifest_or_workflow_references") or []:
            if source != path:
                references[path][source].add("p1_manifest")

    combined_contents = dict(contents)
    combined_contents.update(taskpack_contents)
    markdown_pattern = re.compile(r"\[[^\]]*\]\(([^)\s]+)|(?:href|src)\s*=\s*[\"']([^\"']+)", flags=re.IGNORECASE)
    source_kind_by_path: dict[str, str] = {}
    for source, data in combined_contents.items():
        source_record = records.get(source)
        source_kind_by_path[source] = classify_source(source, source_record)
        text = data.decode("utf-8", errors="replace").replace("\\", "/")
        if "%" in text:
            try:
                normalized_text = urllib.parse.unquote(text)
            except Exception:
                normalized_text = text
        else:
            normalized_text = text
        source_top = source.split("/", 1)[0] if not source.startswith("TASKPACK::") else None
        source_code_like = source_kind_by_path[source] in {"code", "workflow", "package", "deploy", "test", "config"}
        for start, end, pattern in automaton.find(normalized_text):
            for target, kind in pattern_map[pattern]:
                if source == target:
                    continue
                if kind == "project_relative" and source_top != target.split("/", 1)[0] and source_top is not None:
                    continue
                if kind == "extensionless_import" and not source_code_like:
                    continue
                if kind in {"unique_basename", "extensionless_import"} and not is_boundary(normalized_text, start, end):
                    continue
                references[target][source].add(kind)
        if source.startswith("TASKPACK::"):
            continue
        for match in markdown_pattern.finditer(text):
            link = match.group(1) or match.group(2) or ""
            resolved = normalize_link(source, link)
            if resolved in candidate_set and resolved != source:
                references[resolved][source].add("markdown_resolved")

    reference_rows: list[dict[str, str]] = []
    disposition_rows: list[dict[str, str]] = []
    disposition_counts: collections.Counter[str] = collections.Counter()
    static_status_counts: collections.Counter[str] = collections.Counter()
    dynamic_counts: collections.Counter[str] = collections.Counter()
    p3_counts: collections.Counter[str] = collections.Counter()

    for path in sorted(candidates):
        record = records[path]
        candidate = candidates[path]
        scope = project_scope(path, active_projects)
        source_refs = references.get(path, {})
        strong_sources: set[str] = set()
        weak_sources: set[str] = set()
        kind_counts: collections.Counter[str] = collections.Counter()
        source_type_counts: collections.Counter[str] = collections.Counter()
        for source, kinds in source_refs.items():
            for kind in kinds:
                kind_counts[kind] += 1
            if kinds & STRONG_KINDS:
                strong_sources.add(source)
                source_type_counts[source_kind_by_path.get(source, classify_source(source, records.get(source)))] += 1
            else:
                weak_sources.add(source)
        candidate_strong = {source for source in strong_sources if source in candidate_set}
        noncandidate_strong = strong_sources - candidate_strong
        if failures or oversized_text:
            static_status = "SCAN_INCOMPLETE"
        elif noncandidate_strong:
            static_status = "REFERENCED_BY_NONCANDIDATE"
        elif candidate_strong:
            static_status = "REFERENCED_ONLY_BY_CANDIDATES"
        else:
            static_status = "NO_STRONG_REFERENCE"

        runtime_source_types = {"workflow", "package", "deploy", "test", "config", "code", "data_manifest"}
        runtime_ref_count = sum(source_type_counts[source_type] for source_type in runtime_source_types)
        low = path.lower()
        runtimeish_path = (
            record["file_class"] in {"source", "script", "validator", "workflow", "package_manifest", "test_or_fixture", "data", "generated_evidence"}
            or any(fragment in low for fragment in ("/apps/", "/scripts/", "/config/", "/data/", "/metadata/", "/机器治理/"))
        )
        if scope == "other_active_project":
            dynamic_status = "UNKNOWN_EXTERNAL_OWNER_RUNTIME"
        elif runtime_ref_count:
            dynamic_status = "KNOWN_STATIC_RUNTIME_REFERENCE"
        elif runtimeish_path:
            dynamic_status = "POSSIBLE_GLOB_OR_RUNTIME_DISCOVERY"
        else:
            dynamic_status = "NO_DYNAMIC_SIGNAL_IN_SCANNED_REPO"

        duplicate_paths = duplicate_groups.get(record["blob_sha"], [])
        canonical = canonical_by_sha.get(record["blob_sha"])
        disposition, disposition_reason, replacement, replacement_status = replacement_for(
            path, record, candidate, scope, canonical, args.taskpack
        )
        if disposition not in DISPOSITIONS:
            raise RuntimeError(f"invalid disposition: {path} {disposition}")

        if record.get("protected_reason") or scope == "other_active_project":
            p3_eligibility = "BLOCKED_PROTECTED_OR_OWNER"
        elif noncandidate_strong:
            p3_eligibility = "BLOCKED_STATIC_REFERENCE"
        elif candidate_strong:
            p3_eligibility = "NEEDS_ATOMIC_BATCH_REFERENCE_REWRITE"
        elif dynamic_status != "NO_DYNAMIC_SIGNAL_IN_SCANNED_REPO":
            p3_eligibility = "BLOCKED_DYNAMIC_EVIDENCE"
        elif replacement_status == "PLANNED_NOT_IMPLEMENTED":
            p3_eligibility = "BLOCKED_REPLACEMENT_NOT_IMPLEMENTED"
        elif disposition == "keep":
            p3_eligibility = "NOT_APPLICABLE_KEEP"
        elif failures or oversized_text:
            p3_eligibility = "BLOCKED_SCAN_INCOMPLETE"
        else:
            p3_eligibility = "ELIGIBLE_FOR_P3_BATCH_REVIEW"

        # Delete is a P2 classification only when exact replacement, complete scan,
        # no noncandidate/dynamic reference, and OpenAIDatabase ownership are all proven.
        if (
            disposition == "merge"
            and canonical
            and canonical != path
            and replacement_status == "EXACT_BLOB_EXISTS"
            and scope == "openaidatabase"
            and not strong_sources
            and dynamic_status == "NO_DYNAMIC_SIGNAL_IN_SCANNED_REPO"
            and record["file_class"] == "human_document"
            and not failures
            and not oversized_text
        ):
            disposition = "delete"
            disposition_reason = "exact duplicate human record has a canonical peer and no scanned static/dynamic dependency"

        manual_required = "yes" if disposition != "keep" or dynamic_status != "NO_DYNAMIC_SIGNAL_IN_SCANNED_REPO" else "no"
        confidence = (
            "high" if disposition == "keep" and (record.get("protected_reason") or scope == "other_active_project")
            else "medium" if not failures and not oversized_text
            else "low"
        )
        reference_examples = []
        for source in sorted(source_refs):
            reference_examples.append(f"{'+'.join(sorted(source_refs[source]))}@{source}")
            if len(reference_examples) >= 12:
                break

        reference_row = {
            "path": path,
            "project_scope": scope,
            "p1_category": candidate["category"],
            "p1_batch": candidate["batch"],
            "blob_sha": record["blob_sha"],
            "blob_size_bytes": str(record["bytes"]),
            "git_last_modified_utc": record["git_last_modified_utc"] or "",
            "protected_reason": record.get("protected_reason") or "",
            "static_scan_status": static_status,
            "strong_reference_sources": str(len(strong_sources)),
            "noncandidate_strong_sources": str(len(noncandidate_strong)),
            "candidate_strong_sources": str(len(candidate_strong)),
            "weak_reference_sources": str(len(weak_sources)),
            "reference_kind_counts": ";".join(f"{key}={value}" for key, value in sorted(kind_counts.items())),
            "reference_source_type_counts": ";".join(f"{key}={value}" for key, value in sorted(source_type_counts.items())),
            "reference_examples": " | ".join(reference_examples),
            "dynamic_reference_status": dynamic_status,
            "runtime_dependency_status": "PRESENT" if runtime_ref_count else ("UNKNOWN" if dynamic_status != "NO_DYNAMIC_SIGNAL_IN_SCANNED_REPO" else "NO_REPO_SIGNAL"),
            "exact_duplicate_group": record["blob_sha"] if duplicate_paths else "",
            "same_blob_paths": " | ".join(duplicate_paths),
            "canonical_same_blob_path": canonical or "",
            "history_restore_status": "PATH_PRESENT_AT_PINNED_COMMIT",
            "history_restore_command": f"git restore --source={args.commit} -- '{path}'",
            "delete_eligibility": p3_eligibility,
            "manual_evidence_required": manual_required,
            "audited_commit": args.commit,
        }
        reference_rows.append(reference_row)

        disposition_row = {
            "path": path,
            "project_scope": scope,
            "p1_category": candidate["category"],
            "p2_disposition": disposition,
            "disposition_reason": disposition_reason,
            "replacement_truth_source": replacement,
            "replacement_status": replacement_status,
            "static_reference_status": static_status,
            "dynamic_reference_status": dynamic_status,
            "runtime_dependency_status": reference_row["runtime_dependency_status"],
            "restore_method": reference_row["history_restore_command"],
            "history_evidence": f"PATH_PRESENT_AT:{args.commit}",
            "proposed_batch": candidate["batch"],
            "p3_eligibility": p3_eligibility,
            "approval": "pending",
            "confidence": confidence,
            "audited_commit": args.commit,
        }
        disposition_rows.append(disposition_row)
        disposition_counts[disposition] += 1
        static_status_counts[static_status] += 1
        dynamic_counts[dynamic_status] += 1
        p3_counts[p3_eligibility] += 1

    reference_fields = list(reference_rows[0])
    disposition_fields = list(disposition_rows[0])
    with (args.out / "reference_evidence.csv").open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=reference_fields)
        writer.writeheader()
        writer.writerows(reference_rows)
    with (args.out / "disposition_matrix.csv").open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=disposition_fields)
        writer.writeheader()
        writer.writerows(disposition_rows)

    corpus_source_counts = collections.Counter(content_sources.values())
    scanned_bytes = sum(len(data) for data in contents.values()) + sum(len(data) for data in taskpack_contents.values())
    p3_eligible = p3_counts.get("ELIGIBLE_FOR_P3_BATCH_REVIEW", 0)
    history_lines = [
        "# S02-P2 Git History and Restore Policy",
        "",
        f"Generated: `{generated_at}`  ",
        f"Audited commit: `{args.commit}`  ",
        "Mode: read-only evidence. No repository source file, ref, branch, PR, deployment, raw archive, or working-tree path was changed.",
        "",
        "## Decision",
        "",
        "Git history is the only archive for records removed in a future approved S03 batch. Do not create replacement `archive/`, `legacy/`, or `history/` directories, do not rewrite history, and do not force-push.",
        "",
        "This policy does not itself authorize deletion. `disposition_matrix.csv` remains `approval=pending`; S02-P3 must turn only eligible rows into exact atomic batches and the user must approve them.",
        "",
        "## Reference scan coverage",
        "",
        f"- Tracked paths: **{len(records):,}**; P1 candidates: **{len(candidates):,}**.",
        f"- Strict raw/session paths skipped without content access: **{len(strict_raw_paths):,}**; additional raw-like control paths skipped: **{len(raw_like_paths - strict_raw_paths):,}**; raw content reads: **0**.",
        f"- Reference-bearing tracked text planned: **{len(corpus_paths):,}**; scanned: **{len(contents):,}**; pinned TaskPack text sources: **{len(taskpack_contents):,}**; scanned bytes: **{scanned_bytes:,}**.",
        f"- Content sources: `{dict(sorted(corpus_source_counts.items()))}`.",
        f"- Fetch/SHA failures: **{len(failures):,}**; oversized reference-bearing text skipped: **{len(oversized_text):,}**; binary detections excluded: **{len(binary_detected):,}**.",
        "- Static evidence distinguishes noncandidate references from references that occur only inside other candidates. Candidate-only links require an atomic batch rewrite; they are not proof of safe deletion.",
        "- Dynamic loaders, globs, external launchers, app bundles, scheduled automations, and owner workflows cannot be disproven by repository text search alone; affected rows remain blocked or require manual evidence.",
        "",
        "## Disposition and gate summary",
        "",
        f"- Dispositions: `{dict(sorted(disposition_counts.items()))}`.",
        f"- Static reference states: `{dict(sorted(static_status_counts.items()))}`.",
        f"- Dynamic reference states: `{dict(sorted(dynamic_counts.items()))}`.",
        f"- P3 eligibility states: `{dict(sorted(p3_counts.items()))}`; exact rows eligible for P3 batch review: **{p3_eligible:,}**.",
        "- `delete` means a provisional P2 disposition only. It remains non-executable until S02-P3 batching, user approval, replacement verification, and S03 validation.",
        "",
        "## Restore contract",
        "",
        "1. Pin the pre-cleanup commit and verify every approved path exists in that tree before editing.",
        f"2. Before a cleanup commit, restore a path with `git restore --source={args.commit} -- '<path>'`.",
        "3. After an atomic cleanup commit, rollback with `git revert <cleanup_commit>`; never use reset, rebase, filter-repo, or force-push.",
        "4. For rename/merge work, record old path, new truth source, and cleanup commit in the single future cleanup manifest. The pinned pre-cleanup commit is the path-addressable restore source even when later names differ.",
        "5. In this partial clone, an offline restore is not guaranteed when a blob is not hydrated. Validate restore through the pinned GitHub commit before approval; do not create a second archive as compensation.",
        "6. Raw is excluded from cleanup and is append-only; no restore procedure may overwrite a raw source or archive.",
        "",
        "## When Git history is insufficient",
        "",
        "Git history is not sufficient when the candidate is an untracked machine-local file, credential/session store, external database row, mutable cloud object without versioning, or a blob not reachable from the pinned remote commit. Such paths must stay `keep` or receive a separate approved source-of-truth/backup contract; they must not be smuggled into a new repository archive directory.",
        "",
        "## Final-main synchronization override",
        "",
        "The latest user rule overrides per-Stage upload language: later atomic local commits may remain separately revertible, but no Stage-level GitHub upload gate is used. GitHub `main` and App reinstall occur once only after raw ingestion and the overall roadmap/review are complete and validated.",
        "",
        "## Stop conditions carried into S02-P3/S03",
        "",
        "- Any proposed delete with a noncandidate reference, unexplained dynamic loader/glob, unknown external owner/runtime, missing replacement, failed pinned restore, or current release role is blocked.",
        "- Any remote-main drift, dirty unrelated worktree, credential exposure, history rewrite, branch/PR requirement, or raw mutation stops execution.",
        "- Other active projects remain `keep` until their owner/runtime evidence is explicit; a historical-looking directory name is not authority to delete.",
        "- A cleanup batch that creates equal or greater governance/documentation burden is rejected.",
        "",
        "## Rollback of this phase",
        "",
        "There were no repository changes. Discard this temporary directory and regenerate from the pinned P1 artifacts if any evidence is wrong.",
    ]
    (args.out / "history_policy.md").write_text("\n".join(history_lines) + "\n", encoding="utf-8")

    print(json.dumps({
        "status": "GENERATED",
        "audited_commit": args.commit,
        "tracked_paths": len(records),
        "candidate_rows": len(candidates),
        "strict_raw_content_reads": 0,
        "raw_like_control_content_reads": 0,
        "reference_corpus_planned": len(corpus_paths),
        "reference_corpus_scanned": len(contents),
        "taskpack_sources": len(taskpack_contents),
        "scan_failures": len(failures),
        "oversized_text_skipped": len(oversized_text),
        "binary_detected": len(binary_detected),
        "dispositions": dict(sorted(disposition_counts.items())),
        "static_states": dict(sorted(static_status_counts.items())),
        "dynamic_states": dict(sorted(dynamic_counts.items())),
        "p3_states": dict(sorted(p3_counts.items())),
    }, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

