def git_blob_sha(data: bytes) -> str:
    return hashlib.sha1(f"blob {len(data)}\0".encode("ascii") + data).hexdigest()


def git_text(repo: Path, *args: str) -> str:
    env = os.environ.copy()
    env["GIT_NO_LAZY_FETCH"] = "1"
    return subprocess.run(
        ["git", *args], cwd=repo, env=env, check=True, capture_output=True, text=True
    ).stdout.strip()


def is_reference_text(record: dict[str, Any], max_bytes: int) -> bool:
    if record["raw_or_session_metadata_only"]:
        return False
    if int(record["bytes"]) > max_bytes:
        return False
    path = record["path"]
    suffixes = PurePosixPath(path).suffixes
    compound = "".join(suffixes[-2:]).lower() if len(suffixes) >= 2 else ""
    extension = PurePosixPath(path).suffix.lower()
    return (
        extension in TEXT_EXTENSIONS
        or compound in TEXT_EXTENSIONS
        or PurePosixPath(path).name in TEXT_BASENAMES
        or record["file_class"] in {"workflow", "package_manifest"}
    )


def classify_source(path: str, record: dict[str, Any] | None) -> str:
    low = path.lower()
    if path.startswith("TASKPACK::"):
        return "taskpack"
    if record is None:
        return "external"
    if record["file_class"] == "workflow" or "/.github/workflows/" in f"/{low}":
        return "workflow"
    if record["file_class"] == "package_manifest":
        return "package"
    if "wrangler" in low or "/deploy" in low or "cloudflare" in low:
        return "deploy"
    if record["file_class"] == "test_or_fixture" or re.search(r"(^|/)tests?(/|$)", low):
        return "test"
    if "/config/" in f"/{low}" or record["extension"] in {".yaml", ".yml", ".toml", ".ini", ".jsonc"}:
        return "config"
    if record["file_class"] in {"human_document", "owner_entry"}:
        return "documentation"
    if record["file_class"] in {"data", "generated_evidence"} or "/metadata/" in f"/{low}":
        return "data_manifest"
    return "code"


def is_boundary(text: str, start: int, end: int) -> bool:
    before = text[start - 1] if start > 0 else ""
    after = text[end] if end < len(text) else ""

    def path_char(char: str) -> bool:
        return bool(char) and (char.isalnum() or char in PATH_CHARS)

    return not path_char(before) and not path_char(after)


def normalize_link(source: str, link: str) -> str | None:
    link = urllib.parse.unquote(link.strip().strip("<>\"'"))
    if not link or link.startswith("#") or re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", link):
        return None
    link = link.split("#", 1)[0].split("?", 1)[0]
    if not link:
        return None
    if link.startswith("/"):
        return posixpath.normpath(link.lstrip("/"))
    return posixpath.normpath(posixpath.join(posixpath.dirname(source), link))


class ContentCache:
    def __init__(self, path: Path):
        self.path = path
        self.connection = sqlite3.connect(path)
        self.connection.execute(
            "CREATE TABLE IF NOT EXISTS blobs (sha TEXT PRIMARY KEY, content BLOB NOT NULL, source TEXT NOT NULL, bytes INTEGER NOT NULL)"
        )
        self.connection.commit()

    def get(self, sha: str) -> tuple[bytes, str] | None:
        row = self.connection.execute("SELECT content, source FROM blobs WHERE sha = ?", (sha,)).fetchone()
        if row is None:
            return None
        content = bytes(row[0])
        if git_blob_sha(content) != sha:
            raise RuntimeError(f"cache SHA mismatch: {sha}")
        return content, str(row[1])

    def put_many(self, values: list[tuple[str, bytes, str]]) -> None:
        self.connection.executemany(
            "INSERT OR REPLACE INTO blobs(sha, content, source, bytes) VALUES (?, ?, ?, ?)",
            [(sha, content, source, len(content)) for sha, content, source in values],
        )
        self.connection.commit()

    def close(self) -> None:
        self.connection.close()


_thread_local = threading.local()


def fetch_remote(github_repo: str, commit: str, path: str, expected_sha: str) -> tuple[str, bytes, str, str | None]:
    encoded_path = urllib.parse.quote(path, safe="/")
    url = f"http[REDACTED_LOCAL_PATH]"
    if not hasattr(_thread_local, "session"):
        _thread_local.session = requests.Session()
        _thread_local.session.headers.update({"User-Agent": "Codex-S02-P2-read-only-reference-audit"})
    last_error = ""
    for attempt in range(3):
        try:
            response = _thread_local.session.get(url, timeout=(10, 45))
            response.raise_for_status()
            content = response.content
            actual_sha = git_blob_sha(content)
            if actual_sha != expected_sha:
                raise RuntimeError(f"SHA mismatch expected={expected_sha} actual={actual_sha}")
            return path, content, "github_raw_pinned_commit", None
        except Exception as error:  # network and verification failure are both fail-closed
            last_error = f"{type(error).__name__}:{error}"
            time.sleep(0.4 * (attempt + 1))
    return path, b"", "failed", last_error


def choose_canonical(paths: list[str], records: dict[str, dict[str, Any]], candidate_set: set[str]) -> str:
    def score(path: str):
        record = records[path]
        noncandidate = 0 if path not in candidate_set else 1
        protected = 0 if record.get("protected_reason") else 1
        latest = 0 if "latest" in path.lower() else 1
        timestamp = -(int(record.get("git_last_modified_unix") or 0))
        return (protected, noncandidate, latest, timestamp, len(path), path)

    return min(paths, key=score)


def project_scope(path: str, active_projects: set[str]) -> str:
    top = path.split("/", 1)[0]
    if top == "OpenAIDatabase":
        return "openaidatabase"
    if top in active_projects:
        return "other_active_project"
    return "shared_repo"


def replacement_for(
    path: str,
    record: dict[str, Any],
    candidate: dict[str, Any],
    scope: str,
    canonical: str | None,
    taskpack: Path,
) -> tuple[str, str, str, str]:
    """Return disposition, reason, replacement, replacement status."""
    low = path.lower()
    role = record["file_class"]
    tags = set(record.get("candidate_tags") or [])

    if record.get("protected_reason") or record.get("raw_or_session_metadata_only"):
        return "keep", "protected current/raw/owner surface", f"SELF_CURRENT_TRUTH:{path}", "SELF"
    if scope == "other_active_project":
        return "keep", "other active project owner/runtime is outside OpenAIDatabase cleanup authority", f"SELF_CURRENT_TRUTH:{path}", "SELF"

    if scope == "openaidatabase":
        if role == "validator":
            return (
                "merge",
                "active package-referenced validator; consolidate only after assertion-equivalence mapping",
                "OpenAIDatabase/apps/memory-atlas/package.json + planned fast/sync/ui/release profiles",
                "PLANNED_NOT_IMPLEMENTED",
            )
        if path.startswith("OpenAIDatabase/docs/reviews/"):
            return (
                "merge",
                "historical per-stage review should collapse into version-level owner truth",
                "OpenAIDatabase/开发记录.md|OpenAIDatabase/CHANGELOG.md",
                "EXISTS",
            )
        if path.startswith("OpenAIDatabase/docs/acceptance/"):
            return (
                "merge",
                "historical acceptance remains evidence but should consolidate behind current release/readiness entrypoints",
                "OpenAIDatabase/docs/acceptance/memory_atlas_final_acceptance_readiness_acceptance.md|OpenAIDatabase/开发记录.md",
                "EXISTS",
            )
        if path.startswith("OpenAIDatabase/人类可读/"):
            if "参数" in path or "model" in low:
                target = "OpenAIDatabase/模型参数文件.md"
            elif "功能" in path or "feature" in low:
                target = "OpenAIDatabase/功能清单.md"
            else:
                target = "OpenAIDatabase/开发记录.md|OpenAIDatabase/README.md"
            return "merge", "human governance surface exceeds the current-core target", target, "EXISTS"
        if path.startswith("OpenAIDatabase/data/derived/") or path.startswith("OpenAIDatabase/data/processed/") or path.startswith("OpenAIDatabase/data/run_logs/") or path.startswith("OpenAIDatabase/data/memory/"):
            if canonical and canonical != path:
                return "regenerate", "derived/run artifact has an exact canonical peer; preserve run semantics until P3", canonical, "EXACT_BLOB_EXISTS"
            return "keep", "derived/runtime value or regeneration contract is not fully proven", f"SELF_CURRENT_TRUTH:{path}", "SELF"
        if path.startswith("OpenAIDatabase/机器治理/证据与日志/"):
            return (
                "migrate",
                "historical machine evidence should live in Git history while current release evidence remains",
                "GIT_HISTORY + OpenAIDatabase/机器治理/证据与日志/final_delivery/v1_2_final_delivery_cleanup_status.json",
                "GIT_HISTORY_AND_CURRENT_ENTRY_EXISTS",
            )
        if "handoff" in low or "/archive" in low or "/legacy" in low or "taskpack" in low:
            return "migrate", "historical handoff/archive/package is recoverable from Git history", f"GIT_HISTORY:{path}", "GIT_HISTORY"
        if canonical and canonical != path and role in {"human_document", "generated_evidence", "other", "data"}:
            return "merge", "exact duplicate should converge on one current truth after reference rewrite", canonical, "EXACT_BLOB_EXISTS"
        if "report_or_record_review_candidate" in tags:
            return "merge", "repeated report/record should consolidate into the owner entry", "OpenAIDatabase/开发记录.md", "EXISTS"
        return "keep", "current runtime/reference role is not disproven", f"SELF_CURRENT_TRUTH:{path}", "SELF"

    # shared repository surfaces
    if path.startswith("governance/taskpacks/"):
        return "migrate", "superseded shared taskpack should move to Git history after current TaskPack mapping", f"CURRENT_TASKPACK:{taskpack}", "EXTERNAL_CURRENT_TASKPACK_EXISTS"
    if path.startswith("governance/archive/") or "stage" in low or "acceptance" in low or "review" in low:
        return "migrate", "shared historical governance record should be represented by current governance plus Git history", f"GIT_HISTORY:{path}|governance/projects.yaml", "GIT_HISTORY_AND_CURRENT_ENTRY_EXISTS"
    if path.startswith("HANDOFF/") or path.startswith("docs/"):
        return "merge", "shared handoff/documentation should collapse into root governance/current TaskPack", f"AGENTS.md|governance/projects.yaml|CURRENT_TASKPACK:{taskpack}", "EXISTS"
    if role in {"source", "script", "validator", "workflow", "package_manifest", "test_or_fixture"}:
        return "keep", "shared executable/test/workflow surface requires owner and runtime proof", f"SELF_CURRENT_TRUTH:{path}", "SELF"
    if canonical and canonical != path and role in {"human_document", "generated_evidence", "other", "data"}:
        return "merge", "shared exact duplicate can converge only with atomic reference mapping", canonical, "EXACT_BLOB_EXISTS"
    if "generated_evidence_or_snapshot" in tags or "historical_archive" in tags:
        return "migrate", "shared historical/generated evidence should remain recoverable through Git history", f"GIT_HISTORY:{path}", "GIT_HISTORY"
    return "keep", "shared ownership or runtime value is not disproven", f"SELF_CURRENT_TRUTH:{path}", "SELF"


def main() -> None:
    args = parse_args()
    args.out.mkdir(parents=True, exist_ok=True)
    generated_at = dt.datetime.now(tz=dt.timezone.utc).isoformat().replace("+00:00", "Z")

    inventory = json.loads(args.inventory.read_text(encoding="utf-8"))
    cleanup = json.loads(args.candidates.read_text(encoding="utf-8"))
    github_tree = json.loads(args.github_tree.read_text(encoding="utf-8"))
    if inventory["source"]["commit"] != args.commit or cleanup["source_commit"] != args.commit:
        raise RuntimeError("P1 artifacts do not match requested commit")
    if github_tree.get("truncated") is not False:
        raise RuntimeError("GitHub tree is truncated")
    github_records = {
        item["path"]: item for item in github_tree["tree"] if item.get("type") == "blob"
    }
    shallow = git_text(args.repo, "rev-parse", "--is-shallow-repository")
    source_parent_line = git_text(args.repo, "rev-list", "--parents", "-n", "1", args.commit).split()
    source_parent_count = max(0, len(source_parent_line) - 1)
    merge_commit_count = int(git_text(args.repo, "rev-list", "--min-parents=2", "--count", args.commit) or "0")
    submodule_entries = sum(1 for item in github_tree["tree"] if item.get("mode") == "160000")
    symlink_entries = sum(1 for item in github_tree["tree"] if item.get("mode") == "120000")
    gitattributes_paths = sorted(path for path in github_records if PurePosixPath(path).name == ".gitattributes")

    records = {record["path"]: record for record in inventory["files"]}
    candidates = {item["path"]: item for item in cleanup["candidates"]}
    p1_candidate_set = set(candidates)
    discovered_p1_family_gap = sorted(
        path for path in records
        if path.startswith("OpenAIDatabase/docs/reviews/") and path not in candidates
    )
    for path in discovered_p1_family_gap:
        candidates[path] = {
            "path": path,
            "category": "merge",
            "references": ["P2_DISCOVERED:P1 review-family path rule omitted this historical record"],
            "runtime_dependency": "UNKNOWN_PENDING_S02_P2",
            "replacement_source": "OpenAIDatabase/开发记录.md|OpenAIDatabase/CHANGELOG.md",
            "reason": "P2-discovered historical docs/reviews family member",
            "restore_method": f"git restore --source={args.commit} -- '{path}'",
            "batch": "documents",
            "validation": ["S02-P2 full reference scan", "S02-P3 user approval"],
            "approval": "pending",
        }
    candidate_set = set(candidates)
    if len(records) != 7_732 or len(p1_candidate_set) != 3_737 or len(discovered_p1_family_gap) != 40 or len(candidates) != 3_777:
        raise RuntimeError(
            f"unexpected coverage files={len(records)} p1={len(p1_candidate_set)} "
            f"p2_discovered={len(discovered_p1_family_gap)} audited={len(candidates)}"
        )
    if any(records[path]["raw_or_session_metadata_only"] for path in candidates):
        raise RuntimeError("raw-like path leaked into P1 candidates")

    active_projects = set(inventory["summary"].get("active_projects") or ACTIVE_PROJECT_FALLBACK)
    strict_raw_paths = {path for path, record in records.items() if record["raw_append_only_or_session_history"]}
    raw_like_paths = {path for path, record in records.items() if record["raw_or_session_metadata_only"]}
    corpus_paths = sorted(path for path, record in records.items() if is_reference_text(record, args.max_text_bytes))
    oversized_text = sorted(
        path for path, record in records.items()
        if not record["raw_or_session_metadata_only"]
        and int(record["bytes"]) > args.max_text_bytes
        and (PurePosixPath(path).suffix.lower() in TEXT_EXTENSIONS or record["file_class"] in {"workflow", "package_manifest"})
    )

    cache = ContentCache(args.out / "corpus_cache.sqlite")
    contents: dict[str, bytes] = {}
    content_sources: dict[str, str] = {}
    missing_remote: list[tuple[str, str]] = []
    cache_inserts: list[tuple[str, bytes, str]] = []

    for path in corpus_paths:
        sha = records[path]["blob_sha"]
        cached = cache.get(sha)
        if cached is not None:
            contents[path], content_sources[path] = cached[0], "cache_verified"
            continue
        local_path = args.repo / path
        if local_path.is_file():
            data = local_path.read_bytes()
            if git_blob_sha(data) == sha:
                contents[path] = data
                content_sources[path] = "worktree_sha_verified"
                cache_inserts.append((sha, data, "worktree_sha_verified"))
                continue
        missing_remote.append((path, sha))

    if cache_inserts:
        cache.put_many(cache_inserts)
    print(json.dumps({
        "event": "corpus_plan",
        "reference_text_paths": len(corpus_paths),
        "from_cache_or_worktree": len(contents),
        "remote_required": len(missing_remote),
        "oversized_text_skipped": len(oversized_text),
        "strict_raw_skipped": len(strict_raw_paths),
        "raw_like_control_skipped": len(raw_like_paths - strict_raw_paths),
    }, ensure_ascii=False))

    failures: dict[str, str] = {}
    fetched_values: list[tuple[str, bytes, str]] = []
    if missing_remote:
        with concurrent.futures.ThreadPoolExecutor(max_workers=args.workers) as executor:
            futures = {
                executor.submit(fetch_remote, args.github_repo, args.commit, path, sha): (path, sha)
                for path, sha in missing_remote
            }
            completed = 0
            for future in concurrent.futures.as_completed(futures):
                path, expected_sha = futures[future]
                try:
                    returned_path, data, source, error = future.result()
                except Exception as error_obj:
                    failures[path] = f"{type(error_obj).__name__}:{error_obj}"
                    continue
                if returned_path != path or error:
                    failures[path] = error or "returned path mismatch"
                    continue
                contents[path] = data
                content_sources[path] = source
                fetched_values.append((expected_sha, data, source))
                completed += 1
                if completed % 250 == 0:
                    print(json.dumps({"event": "remote_progress", "completed": completed, "required": len(missing_remote)}))
        if fetched_values:
            cache.put_many(fetched_values)
    cache.close()

    # Drop accidental binary detections from the searchable corpus without emitting content.
    binary_detected = sorted(path for path, data in contents.items() if b"\0" in data[:8192])
    for path in binary_detected:
        del contents[path]
        content_sources.pop(path, None)

    taskpack_contents: dict[str, bytes] = {}
    for path in sorted(args.taskpack.rglob("*")):
        if not path.is_file() or path.stat().st_size > args.max_text_bytes:
            continue
        if path.suffix.lower() not in TEXT_EXTENSIONS and path.name not in TEXT_BASENAMES:
            continue
        data = path.read_bytes()
        if b"\0" in data[:8192]:
            continue
        taskpack_contents[f"TASKPACK::{path.relative_to(args.taskpack).as_posix()}"] = data

    if failures:
        print(json.dumps({"event": "corpus_failures", "count": len(failures), "examples": dict(list(sorted(failures.items()))[:10])}, ensure_ascii=False))

    # Build exact duplicate/canonical mappings from metadata only.
    sha_groups: dict[str, list[str]] = collections.defaultdict(list)
    for path, record in records.items():
        if not record["raw_append_only_or_session_history"] and int(record["bytes"]) > 0:
            sha_groups[record["blob_sha"]].append(path)
    duplicate_groups = {sha: sorted(paths) for sha, paths in sha_groups.items() if len(paths) > 1}
    canonical_by_sha = {
        sha: choose_canonical(paths, records, candidate_set) for sha, paths in duplicate_groups.items()
    }

    basename_counts = collections.Counter(PurePosixPath(path).name for path in records)
    pattern_map: dict[str, list[tuple[str, str]]] = collections.defaultdict(list)

    def add_pattern(pattern: str, target: str, kind: str) -> None:
        pattern = pattern.replace("\\", "/")
        if len(pattern) >= 4:
            value = (target, kind)
            if value not in pattern_map[pattern]:
                pattern_map[pattern].append(value)

    for path in sorted(candidates):
        add_pattern(path, path, "full_path")
        if "/" in path:
            relative = path.split("/", 1)[1]
            add_pattern(relative, path, "project_relative")
        basename = PurePosixPath(path).name
        if basename_counts[basename] == 1 and len(basename) >= 6:
            add_pattern(basename, path, "unique_basename")
        suffix = PurePosixPath(path).suffix.lower()
        if suffix in CODE_EXTENSIONS:
            extensionless = path[: -len(suffix)]
            add_pattern(extensionless, path, "extensionless_import")
            if "/" in extensionless:
                add_pattern(extensionless.split("/", 1)[1], path, "extensionless_import")

    automaton = AhoCorasick(pattern_map)
    references: dict[str, dict[str, set[str]]] = collections.defaultdict(lambda: collections.defaultdict(set))

    # Preserve P1 package/workflow evidence as an independent source.
    for path, record in records.items():
        if path not in candidates:
            continue
        for source in record.get("manifest_or_workflow_references") or []:
            if source != path:
                references[path][source].add("p1_manifest")

    combined_contents = dict(contents)
    combined_contents.update(taskpack_contents)
    markdown_pattern = re.compile(r"\[[^\]]*\]\(([^)\s]+)|(?:href|src)\s*=\s*[\"']([^\"']+)", flags=re.IGNORECASE)
    source_kind_by_path: dict[str, str] = {}
    for source, data in combined_contents.items():
        source_record = records.get(source)
        source_kind_by_path[source] = classify_source(source, source_record)
        text = data.decode("utf-8", errors="replace").replace("\\", "/")
        if "%" in text:
            try:
                normalized_text = urllib.parse.unquote(text)
