#!/usr/bin/env python3
"""Generate S02-P3 read-only cleanup batches, protection set, and S03 plan."""

from __future__ import annotations

import argparse
import collections
import csv
import datetime as dt
import hashlib
import json
import sqlite3
from pathlib import Path, PurePosixPath
from typing import Any


COMMIT = "5e48e739774575f4d198d6268271e557de434897"
BATCH_ORDER = ["documents", "governance", "frontend_scripts", "validation", "generated"]
PROPOSED_REMOVALS = {
    "OpenAIDatabase/docs/reviews/memory_atlas_v1_1_5_stage0_review.md",
    "docs/governance/agent_loop/NEW_CHATGPT_HANDOFF_PROMPT.md",
    "docs/governance/agent_loop/REVIEW_CHECKLIST.md",
    "docs/governance/agent_loop/STAGE_C2_C3_D1_USAGE.md",
}
SEMANTICALLY_PROTECTED_FIXTURES = {
    "docs/governance/agent_loop/examples/invalid_missing_project_taskpack.md": "missing-project negative fixture",
    "docs/governance/agent_loop/examples/minimal_t1_taskpack_escape_slash.md": "JSON escape and slash-heading fixture",
    "docs/governance/agent_loop/examples/minimal_t1_taskpack_zh.md": "Chinese heading and localization fixture",
}
WRITE_TARGETS = {
    "scripts/agent_loop/README.md": {
        "max_added_bytes": 3_000,
        "max_added_lines": 50,
        "required_content": [
            "C2/C3/D1 current trigger, duplicate-suppression, and local dry-run behavior",
            "T1 one-paid-call default and T2 fail-closed status",
            "current troubleshooting and artifact-review-before-rerun guidance",
        ],
    },
    "docs/governance/agent_loop/TASK_PACK_DUAL_PLANE_SPEC.md": {
        "max_added_bytes": 2_000,
        "max_added_lines": 30,
        "required_content": [
            "ChatGPT authoring rules with explicit path boundaries and BLOCKED routing",
            "review checklist with P0-P3 severity and merge impact",
        ],
    },
}
ALLOWED_CHANGED_PATHS = PROPOSED_REMOVALS | set(WRITE_TARGETS)
CRITICAL_PROTECTED_REASONS = {
    "current_deployment_configuration",
    "current_goal_release_evidence",
    "current_openaidatabase_live_evidence",
    "openaidatabase_final_readiness_or_rollback_evidence",
    "root_governance_required",
}


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--inventory", type=Path, required=True)
    parser.add_argument("--reference", type=Path, required=True)
    parser.add_argument("--disposition", type=Path, required=True)
    parser.add_argument("--cache", type=Path, required=True)
    parser.add_argument("--out", type=Path, required=True)
    return parser.parse_args()


def file_sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def read_csv(path: Path) -> list[dict[str, str]]:
    return list(csv.DictReader(path.open(encoding="utf-8", newline="")))


def stable_digest(values: list[dict[str, Any]]) -> str:
    payload = json.dumps(values, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def deferral_reason(path: str, row: dict[str, str]) -> str:
    if path in SEMANTICALLY_PROTECTED_FIXTURES:
        return "P3_SEMANTIC_REVIEW_FOUND_UNIQUE_FIXTURE_NOT_REPLACEABLE"
    return {
        "BLOCKED_STATIC_REFERENCE": "NONCANDIDATE_STATIC_REFERENCE_PRESENT",
        "NEEDS_ATOMIC_BATCH_REFERENCE_REWRITE": "CANDIDATE_ONLY_REFERENCE_CLOSURE_AND_REWRITE_MAPPING_NOT_PROVEN",
        "BLOCKED_DYNAMIC_EVIDENCE": "DYNAMIC_OR_RUNTIME_DEPENDENCY_NOT_DISPROVEN",
        "NEEDS_MANUAL_WEAK_REFERENCE_REVIEW": "WEAK_REFERENCE_REQUIRES_MANUAL_EVIDENCE",
        "ELIGIBLE_FOR_P3_BATCH_REVIEW": "P3_SEMANTIC_REVIEW_RECLASSIFIED_AS_PROTECTED",
    }[row["p3_eligibility"]]


def main() -> None:
    args = parse_args()
    args.out.mkdir(parents=True, exist_ok=True)
    generated_at = dt.datetime.now(tz=dt.timezone.utc).isoformat().replace("+00:00", "Z")

    inventory = json.loads(args.inventory.read_text(encoding="utf-8"))
    records = {row["path"]: row for row in inventory["files"]}
    reference = read_csv(args.reference)
    disposition = read_csv(args.disposition)
    ref_by_path = {row["path"]: row for row in reference}
    disp_by_path = {row["path"]: row for row in disposition}
    if inventory["source"]["commit"] != COMMIT:
        raise RuntimeError("inventory source commit drift")
    if len(records) != 7_740 or len(reference) != 3_778 or len(disposition) != 3_778:
        raise RuntimeError("input coverage drift")
    if set(ref_by_path) != set(disp_by_path):
        raise RuntimeError("P2 path-set mismatch")
    if any(row["audited_commit"] != COMMIT for row in reference + disposition):
        raise RuntimeError("P2 audited commit drift")
    if any(row["approval"] != "pending" for row in disposition):
        raise RuntimeError("unexpected approved/rejected P2 row")
    if any(row["p2_disposition"] == "delete" for row in disposition):
        raise RuntimeError("P2 direct delete classification is not accepted")

    input_hashes = {
        "repo_inventory.json": file_sha256(args.inventory),
        "reference_evidence.csv": file_sha256(args.reference),
        "disposition_matrix.csv": file_sha256(args.disposition),
    }
    original_eligible = {
        path for path, row in disp_by_path.items()
        if row["p3_eligibility"] == "ELIGIBLE_FOR_P3_BATCH_REVIEW"
    }
    if original_eligible != PROPOSED_REMOVALS | set(SEMANTICALLY_PROTECTED_FIXTURES):
        raise RuntimeError("P2 eligible set drift")
    if not ALLOWED_CHANGED_PATHS <= set(records):
        raise RuntimeError("allowed S03 path absent from pinned inventory")
    if any(records[path]["raw_or_session_metadata_only"] for path in ALLOWED_CHANGED_PATHS):
        raise RuntimeError("raw-like path entered allowed S03 changes")

    cache = sqlite3.connect(args.cache)

    def line_count(path: str) -> int:
        row = cache.execute(
            "SELECT b.content FROM scanned_paths s JOIN blobs b ON b.sha=s.sha WHERE s.path=?",
            (path,),
        ).fetchone()
        if row is None:
            raise RuntimeError(f"non-raw corpus content missing: {path}")
        data = bytes(row[0])
        return data.count(b"\n") + (0 if not data or data.endswith(b"\n") else 1)

    removal_entries: dict[str, dict[str, Any]] = {}
    for path in sorted(PROPOSED_REMOVALS):
        disp = disp_by_path[path]
        ref = ref_by_path[path]
        if disp["p3_eligibility"] != "ELIGIBLE_FOR_P3_BATCH_REVIEW":
            raise RuntimeError(f"proposed path is not P2 eligible: {path}")
        if ref["strong_reference_sources"] != "0" or ref["weak_reference_sources"] != "0":
            raise RuntimeError(f"proposed path retains a scanned reference: {path}")
        if ref["dynamic_reference_status"] != "NO_DYNAMIC_SIGNAL_IN_SCANNED_REPO":
            raise RuntimeError(f"proposed path retains dynamic uncertainty: {path}")
        is_legacy_review = path.startswith("OpenAIDatabase/docs/reviews/")
        removal_entries[path] = {
            "path": path,
            "blob_sha": records[path]["blob_sha"],
            "tree_mode": ref["tree_mode"],
            "bytes": int(records[path]["bytes"]),
            "lines": line_count(path),
            "project_scope": disp["project_scope"],
            "file_class": records[path]["file_class"],
            "p2_disposition": disp["p2_disposition"],
            "p2_p3_eligibility": disp["p3_eligibility"],
            "planned_action": (
                "REMOVE_CURRENT_PATH_USE_CHANGELOG_AND_GIT_HISTORY"
                if is_legacy_review
                else "CONSOLIDATE_CURRENT_SEMANTICS_THEN_REMOVE_REDUNDANT_PATH"
            ),
            "replacement_truth_source": disp["replacement_truth_source"],
            "replacement_status": disp["replacement_status"],
            "static_reference_status": disp["static_reference_status"],
            "dynamic_reference_status": disp["dynamic_reference_status"],
            "runtime_dependency_status": disp["runtime_dependency_status"],
            "semantic_precondition": (
                "OpenAIDatabase/CHANGELOG.md retains the v1.1.5 Part 1 Stage 0 review summary"
                if is_legacy_review
                else "required current guidance is consolidated within the guarded write budget"
            ),
            "restore_source": COMMIT,
            "restore_command": disp["restore_method"],
            "approval": "pending",
            "execution_authorized": False,
            "audited_commit": COMMIT,
        }

    cache.close()

    deferred_entries: list[dict[str, Any]] = []
    for path, row in sorted(disp_by_path.items()):
        if row["p2_disposition"] == "keep" or path in PROPOSED_REMOVALS:
            continue
        deferred_entries.append({
            "path": path,
            "project_scope": row["project_scope"],
            "p2_disposition": row["p2_disposition"],
            "p3_eligibility": row["p3_eligibility"],
            "proposed_batch": row["proposed_batch"],
            "static_reference_status": row["static_reference_status"],
            "dynamic_reference_status": row["dynamic_reference_status"],
            "replacement_truth_source": row["replacement_truth_source"],
            "deferral_reason": deferral_reason(path, row),
            "s03_in_scope": False,
            "approval": "pending",
            "audited_commit": COMMIT,
        })
    deferred_gate_counts = collections.Counter(row["p3_eligibility"] for row in deferred_entries)
    deferred_disposition_counts = collections.Counter(row["p2_disposition"] for row in deferred_entries)
    deferred_batch_counts = collections.Counter(row["proposed_batch"] for row in deferred_entries)

    other_active_projects = sorted(set(inventory["summary"]["active_projects"]) - {"OpenAIDatabase"})
    protected_entries: list[dict[str, Any]] = []
    for path in sorted(set(records) - ALLOWED_CHANGED_PATHS):
        record = records[path]
        disp = disp_by_path.get(path)
        secondary: list[str] = []
        if record["protected_reason"]:
            primary = "INVENTORY_PROTECTED"
            secondary.append(f"INVENTORY_REASON:{record['protected_reason']}")
        elif disp is not None and disp["p2_disposition"] == "keep":
            primary = "P2_KEEP"
        elif disp is not None:
            primary = "P3_DEFERRED_NONKEEP"
        else:
            primary = "NOT_CLEANUP_CANDIDATE_DENY_BY_DEFAULT"
        if disp is not None:
            secondary.extend([
                f"P2_DISPOSITION:{disp['p2_disposition']}",
                f"P3_GATE:{disp['p3_eligibility']}",
            ])
        if path in SEMANTICALLY_PROTECTED_FIXTURES:
            secondary.append("P3_UNIQUE_FIXTURE_SEMANTICS")
        top = path.split("/", 1)[0]
        if top in other_active_projects:
            secondary.append("OTHER_ACTIVE_PROJECT_PREFIX")
        if record["raw_or_session_metadata_only"]:
            secondary.append("RAW_OR_RAWLIKE_METADATA_ONLY")
        if path.startswith("FINAL_ACCEPTANCE_BUNDLE/"):
            secondary.append("CURRENT_FINAL_ACCEPTANCE_BUNDLE")
        protected_entries.append({
            "path": path,
            "blob_sha": record["blob_sha"],
            "bytes": int(record["bytes"]),
            "top_level": record["top_level"],
            "file_class": record["file_class"],
            "primary_reason": primary,
            "secondary_reasons": sorted(set(secondary)),
            "s03_change_allowed": False,
            "audited_commit": COMMIT,
        })
    protected_primary_counts = collections.Counter(row["primary_reason"] for row in protected_entries)
    protected_secondary_counts = collections.Counter(
        reason for row in protected_entries for reason in row["secondary_reasons"]
    )

    selector_sets = {
        "P2_KEEP": {path for path, row in disp_by_path.items() if row["p2_disposition"] == "keep"},
        "P2_NONKEEP_NOT_S03": {
            path for path, row in disp_by_path.items()
            if row["p2_disposition"] != "keep" and path not in PROPOSED_REMOVALS
        },
        "INVENTORY_PROTECTED": {path for path, row in records.items() if row["protected_reason"]},
        "RAW_OR_RAWLIKE": {path for path, row in records.items() if row["raw_or_session_metadata_only"]},
        "OTHER_ACTIVE_PROJECT": {
            path for path in records if path.split("/", 1)[0] in other_active_projects
        },
        "CRITICAL_SURFACE": {
            path for path, row in records.items() if row["protected_reason"] in CRITICAL_PROTECTED_REASONS
        },
    }
    selector_union = set().union(*selector_sets.values())
    protected_payload = {
        "schema_version": "s02-p3.protected-paths.v1",
        "stage": "S02",
        "phase": "P3",
        "task": "S02-P3-T2",
        "generated_at_utc": generated_at,
        "source_commit": COMMIT,
        "root_tree": inventory["source"]["root_tree"],
        "input_sha256": input_hashes,
        "mode": "READ_ONLY_PLAN",
        "default_policy": "DENY_ALL_TRACKED_PATHS_EXCEPT_EXACT_ALLOWED_CHANGES",
        "s03_execution_authorized": False,
        "approval_status": "pending_user_and_stage_review",
        "tracked_path_count": len(records),
        "allowed_change_path_count": len(ALLOWED_CHANGED_PATHS),
        "protected_path_count": len(protected_entries),
        "allowed_change_entries": [
            {
                "path": path,
                "permission": "remove_only",
                "batch": disp_by_path[path]["proposed_batch"],
                "approval": "pending",
                "execution_authorized": False,
            }
            for path in sorted(PROPOSED_REMOVALS)
        ] + [
            {
                "path": path,
                "permission": "modify_only_semantic_consolidation",
                "batch": "governance",
                "approval": "pending",
                "execution_authorized": False,
                "guard": WRITE_TARGETS[path],
            }
            for path in sorted(WRITE_TARGETS)
        ],
        "protected_prefix_rules": {
            "other_active_project_prefixes": other_active_projects,
            "raw_or_rawlike": "inventory.raw_or_session_metadata_only == true",
            "final_acceptance": "path starts with FINAL_ACCEPTANCE_BUNDLE/",
            "critical_protected_reasons": sorted(CRITICAL_PROTECTED_REASONS),
            "note": "Prefix/selectors add explanation; the exact deny-by-default path partition is authoritative.",
        },
        "selector_summary": {
            "component_counts": {key: len(value) for key, value in selector_sets.items()},
            "deduplicated_union_count": len(selector_union),
            "not_in_selector_union_count": len(records) - len(selector_union),
            "not_protected_does_not_mean_authorized": True,
        },
        "protected_summary": {
            "by_primary_reason": dict(sorted(protected_primary_counts.items())),
            "by_secondary_reason": dict(sorted(protected_secondary_counts.items())),
        },
        "raw_protection": {
            "strict_raw_or_session_paths": sum(row["raw_append_only_or_session_history"] for row in records.values()),
            "additional_raw_like_paths": sum(row["raw_or_session_metadata_only"] for row in records.values())
            - sum(row["raw_append_only_or_session_history"] for row in records.values()),
            "raw_content_reads": 0,
            "all_raw_like_paths_protected": True,
        },
        "semantic_fixture_protection": [
            {"path": path, "unique_semantics": semantics, "s03_change_allowed": False}
            for path, semantics in sorted(SEMANTICALLY_PROTECTED_FIXTURES.items())
        ],
        "protected_entries": protected_entries,
        "invariants": [
            "allowed and protected path sets are disjoint",
            "allowed union protected equals the complete pinned tracked tree",
            "all raw/raw-like, inventory-protected, final-acceptance, and other-active-project paths are protected",
            "a path absent from explanatory selectors remains protected by deny-by-default",
            "any BASE, input SHA, path count, or approval drift invalidates this plan",
        ],
    }
    protected_path = args.out / "protected_paths.json"
