    protected_sha = file_sha256(protected_path)

    write_entries = {
        path: {
            "path": path,
            "permission": "modify_only_semantic_consolidation",
            "max_added_bytes": spec["max_added_bytes"],
            "max_added_lines": spec["max_added_lines"],
            "required_content": spec["required_content"],
            "new_file_forbidden": True,
            "approval": "pending",
