                {"command": "git diff --check", "expected": "exit 0"},
            ],
            "stops": [
                "the legacy review contains current facts absent from CHANGELOG and Git history",
                "any static, dynamic, weak, runtime, Wave2, or current-surface reference appears after BASE repin",
            ],
        },
        "governance": {
            "id": "S03-B2-GOVERNANCE",
            "removals": sorted(PROPOSED_REMOVALS - {"OpenAIDatabase/docs/reviews/memory_atlas_v1_1_5_stage0_review.md"}),
            "writes": sorted(WRITE_TARGETS),
            "validation": [
                {"command": "PYTHONPYCACHEPREFIX=/tmp/s03-agent-loop-pycache python3 -m py_compile scripts/agent_loop/*.py", "expected": "exit 0 without repository __pycache__"},
                {"command": "python3 scripts/agent_loop/validate_taskpack.py --taskpack docs/governance/agent_loop/examples/minimal_t1_taskpack.md", "expected": "TASKPACK_VALIDATION=PASS"},
                {"command": "python3 scripts/agent_loop/validate_taskpack.py --taskpack docs/governance/agent_loop/examples/minimal_t1_taskpack_zh.md", "expected": "TASKPACK_VALIDATION=PASS; retained localization fixture"},
                {"command": "python3 scripts/agent_loop/autofill_taskpack_metadata.py --input docs/governance/agent_loop/examples/minimal_t1_taskpack_escape_slash.md --output /tmp/s03_escape_slash_normalized.md && python3 scripts/agent_loop/validate_taskpack.py --taskpack /tmp/s03_escape_slash_normalized.md", "expected": "exit 0; retained escape fixture"},
                {"command": "bash -lc '! python3 scripts/agent_loop/validate_taskpack.py --taskpack docs/governance/agent_loop/examples/invalid_missing_project_taskpack.md'", "expected": "exit 0 because the retained negative fixture fails validation"},
                {"command": "python3 scripts/agent_loop/route_taskpack.py --taskpack docs/governance/agent_loop/examples/minimal_t1_taskpack.md", "expected": "unambiguous route result"},
                {"command": "git diff --check", "expected": "exit 0"},
            ],
            "stops": [
                "canonical README/spec cannot carry all required current semantics within the 5,000-byte/80-line budget",
                "a unique fixture, route, workflow, or runtime dependency would be removed",
                "retained negative, escape, or Chinese fixture validation changes behavior",
            ],
        },
        "frontend_scripts": {"id": "S03-B3-FRONTEND-SCRIPTS", "removals": [], "writes": [], "validation": [], "stops": ["any frontend/script path is added without a new P2 audit"]},
        "validation": {"id": "S03-B4-VALIDATION", "removals": [], "writes": [], "validation": [], "stops": ["any validator path is added without assertion-equivalence proof"]},
        "generated": {"id": "S03-B5-GENERATED", "removals": [], "writes": [], "validation": [], "stops": ["any raw, dynamic, or unproven regeneration path is added"]},
    }
    batch_rows: list[dict[str, Any]] = []
    for order, category in enumerate(BATCH_ORDER, start=1):
        spec = batch_specs[category]
        removals = [removal_entries[path] for path in spec["removals"]]
        writes = [write_entries[path] for path in spec["writes"]]
        allowed = sorted(set(spec["removals"]) | set(spec["writes"]))
        active = bool(allowed)
        batch_rows.append({
            "id": spec["id"],
            "category": category,
            "order": order,
            "status": "PROPOSED_PENDING_USER_APPROVAL" if active else "SKIP_NO_SAFE_SCOPE",
            "scope": "exact paths only; no glob expansion",
            "removal_entries": removals,
            "guarded_write_targets": writes,
            "allowed_changed_paths": allowed,
            "approval_scope_digest": stable_digest([
                {"path": path, "blob_sha": records[path]["blob_sha"], "permission": "remove_only" if path in PROPOSED_REMOVALS else "modify_only"}
                for path in allowed
            ]),
            "estimated_change": {
                "remove_files": len(removals),
                "remove_bytes": sum(row["bytes"] for row in removals),
                "remove_lines": sum(row["lines"] for row in removals),
                "modify_existing_files": len(writes),
                "max_added_bytes": sum(row["max_added_bytes"] for row in writes),
                "max_added_lines": sum(row["max_added_lines"] for row in writes),
                "public_scripts_delta": 0,
                "validator_files_delta": 0,
                "default_codex_context_files_delta": 0,
            },
            "preconditions": [
                f"live main and local S03 BASE are re-pinned to the same commit descended from {COMMIT}",
                "user approves this exact digest and the S02 Stage review passes",
                "all removal paths retain zero strong/weak/dynamic/runtime references after repin",
                "protected-path and allowed-change partitions validate before editing",
            ] if active else ["no safe eligible path exists; do not create a commit"],
            "validation_commands": spec["validation"],
            "rollback": {
                "default_command": "git revert <batch_commit>",
                "rehearsal_location": "disposable_clean_worktree",
                "selective_restore": "use pinned BASE path restore only when whole-batch revert is unsuitable; validate and commit recovery separately",
            },
            "stop_conditions": spec["stops"] + [
                "remote main changes during the batch",
                "changed paths exceed the exact allowed list",
                "raw, credentials, branches, PRs, deploys, history rewrite, or force operations become necessary",
            ],
            "commit_policy": {
                "empty_commit_forbidden": True,
                "single_parent_required": True,
                "one_batch_one_commit": True,
                "push_in_this_stage": False,
                "commit_allowed_now": False,
            },
            "approval": "pending" if active else "not_applicable_no_scope",
            "execution_authorized": False,
        })

    removal_bytes = sum(row["bytes"] for row in removal_entries.values())
    removal_lines = sum(row["lines"] for row in removal_entries.values())
    write_budget_bytes = sum(row["max_added_bytes"] for row in write_entries.values())
    write_budget_lines = sum(row["max_added_lines"] for row in write_entries.values())
    package_path = "OpenAIDatabase/apps/memory-atlas/package.json"
    package_content = sqlite3.connect(args.cache).execute(
        "SELECT b.content FROM scanned_paths s JOIN blobs b ON b.sha=s.sha WHERE s.path=?",
        (package_path,),
    ).fetchone()
    if package_content is None:
        raise RuntimeError("Memory Atlas package manifest unavailable")
    package = json.loads(bytes(package_content[0]))
    package_scripts = package.get("scripts") or {}
    public_script_count = len(package_scripts)
    validate_script_count = sum(str(name).startswith("validate") for name in package_scripts)
    markdown_count = sum(PurePosixPath(path).suffix.lower() == ".md" for path in records)
    validator_count = sum(row["file_class"] == "validator" for row in records.values())
    oai_validator_count = sum(row["file_class"] == "validator" and path.startswith("OpenAIDatabase/") for path, row in records.items())
    context_paths = [
        "AGENTS.md",
        "OpenAIDatabase/AGENTS.md",
        "OpenAIDatabase/data/derived/personalization/codex_personalization.md",
    ]
    context_connection = sqlite3.connect(args.cache)
    context_bytes = 0
    context_lines = 0
    for path in context_paths:
        row = context_connection.execute(
            "SELECT b.content FROM scanned_paths s JOIN blobs b ON b.sha=s.sha WHERE s.path=?",
            (path,),
        ).fetchone()
        if row is None:
            raise RuntimeError(f"startup context unavailable: {path}")
        data = bytes(row[0])
        context_bytes += len(data)
        context_lines += data.count(b"\n") + (0 if not data or data.endswith(b"\n") else 1)
    context_connection.close()
    metrics = {
        "proposed_removal_files": len(removal_entries),
        "proposed_removal_bytes": removal_bytes,
        "proposed_removal_lines": removal_lines,
        "guarded_write_target_files": len(write_entries),
        "write_budget_max_bytes": write_budget_bytes,
        "write_budget_max_lines": write_budget_lines,
        "expected_net_files_reduction": len(removal_entries),
        "expected_net_bytes_reduction_min": removal_bytes - write_budget_bytes,
        "expected_net_lines_reduction_min": removal_lines - write_budget_lines,
        "public_scripts_reduction": 0,
        "validator_files_reduction": 0,
        "default_codex_startup_context_files_reduction": 0,
    }
    baseline_metrics = {
        "tracked_files": len(records),
        "tracked_bytes": sum(int(row["bytes"]) for row in records.values()),
        "markdown_files": markdown_count,
        "memory_atlas_package_scripts": public_script_count,
        "memory_atlas_validate_prefixed_scripts": validate_script_count,
        "validator_files": validator_count,
        "openaidatabase_validator_files": oai_validator_count,
        "default_codex_startup_context_files": len(context_paths),
        "default_codex_startup_context_bytes": context_bytes,
        "default_codex_startup_context_lines": context_lines,
    }
    cleanup_payload = {
        "schema_version": "s02-p3.cleanup-batches.v1",
        "stage": "S02",
        "phase": "P3",
        "task": "S02-P3-T1_T3",
        "generated_at_utc": generated_at,
        "source_commit": COMMIT,
        "root_tree": inventory["source"]["root_tree"],
        "input_sha256": input_hashes,
        "protected_paths_ref": {"path": str(protected_path), "sha256": protected_sha},
        "mode": "READ_ONLY_PLAN",
        "s03_execution_authorized": False,
        "approval_status": "pending_user_and_stage_review",
        "push_policy": "FINAL_ONLY_NO_STAGE_UPLOAD",
        "selection_policy": {
            "approach": "MINIMUM_SAFE_SEMANTIC_SCOPE",
            "p2_rows": len(disposition),
            "p2_keep": sum(row["p2_disposition"] == "keep" for row in disposition),
            "p2_nonkeep": sum(row["p2_disposition"] != "keep" for row in disposition),
            "p2_batch_review_eligible": len(original_eligible),
            "p3_proposed_removals": len(PROPOSED_REMOVALS),
            "p3_semantic_reclassified_protected": len(SEMANTICALLY_PROTECTED_FIXTURES),
            "deferred_nonkeep": len(deferred_entries),
            "guarded_write_targets": len(WRITE_TARGETS),
            "allowed_changed_paths": len(ALLOWED_CHANGED_PATHS),
        },
        "baseline_metrics": baseline_metrics,
        "metrics": metrics,
        "batch_order": BATCH_ORDER,
        "batches": batch_rows,
        "deferred_summary": {
            "count": len(deferred_entries),
            "by_p3_gate": dict(sorted(deferred_gate_counts.items())),
            "by_disposition": dict(sorted(deferred_disposition_counts.items())),
            "by_batch": dict(sorted(deferred_batch_counts.items())),
        },
        "deferred_entries": deferred_entries,
        "semantic_reclassified_protected": [
            {
                "path": path,
                "unique_semantics": semantics,
                "p2_disposition": disp_by_path[path]["p2_disposition"],
                "p2_p3_eligibility": disp_by_path[path]["p3_eligibility"],
                "p3_decision": "PROTECT_UNIQUE_REGRESSION_OR_LOCALIZATION_SEMANTICS",
                "approval": "pending",
            }
            for path, semantics in sorted(SEMANTICALLY_PROTECTED_FIXTURES.items())
        ],
        "global_invariants": [
            "only P2 batch-review-eligible rows may be considered, followed by P3 semantic review",
            "the three unique fixtures remain protected and retain their distinct validation behavior",
            "five batch records exist; no safe scope means no commit",
            "every non-keep path is either a proposed removal or an exact deferred entry",
            "every tracked path is either protected or an exact allowed change",
            "raw content reads remain zero and raw paths remain protected",
            "all approvals are pending and S03 execution authorization remains false",
        ],
        "global_stop_conditions": [
            "BASE or live remote main differs from the audited source without a full re-audit",
            "any input artifact SHA or path-set count changes",
            "any proposed path gains a strong, weak, dynamic, runtime, governance, or current-surface dependency",
            "the protected/allowed partition fails or changed files exceed the exact allowlist",
            "the governance consolidation exceeds its write budget or loses unique semantics",
            "raw, secrets, branch/PR, deploy, history rewrite, or external-service work becomes necessary",
        ],
        "approval_gate": {
            "user_batch_approval": "pending",
            "s02_stage_review": "pending",
            "separate_s03_start_authorization": "required",
            "base_repin_after_approval": "required",
            "approval_digest_scope": "exact path + blob SHA + permission + batch digest",
        },
    }
    batches_path = args.out / "cleanup_batches.json"
    batches_path.write_text(json.dumps(cleanup_payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    plan_lines = [
        "# S03 精确清理计划（S02-P3，只读提案）",
        "",
        f"生成时间：`{generated_at}`  ",
        f"审计基线：`{COMMIT}`  ",
        "S03 执行授权：**NO**  ",
        "用户审批：**PENDING**  ",
        "Stage 复审：**PENDING**",
        "",
        "本文件只让用户审阅未来 S03 的精确影响；本 Phase 不删除、不改写、不提交、不上传、不部署、不重装 App。批准本提案与另行授权开始 S03 是两个独立 gate。",
        "",
        "## 选择结论",
        "",
        f"P2 共 **3,778** 行，其中 **751** 个 non-keep。P2 初步允许 7 项进入批次复核；P3 语义复核发现 3 个独立 fixture 不能被 canonical minimal fixture 替代，因此只提出 **4 个移除路径**和 **2 个受控写入目标**。其余 **747** 个 non-keep 全部 defer。",
        "",
        "未采用的方案：把 105 个 candidate-only 引用项或全部 751 个 non-keep 加入 S03。原因是引用闭包、动态依赖、弱引用或替代证明尚未关闭。",
        "",
        "## 精确移除路径",
        "",
        "| Batch | Path | Action | Bytes | Lines | Replacement |",
        "|---|---|---|---:|---:|---|",
    ]
    for category in ("documents", "governance"):
        row = next(item for item in batch_rows if item["category"] == category)
        for entry in row["removal_entries"]:
            plan_lines.append(
                f"| {category} | `{entry['path']}` | {entry['planned_action']} | {entry['bytes']:,} | {entry['lines']:,} | `{entry['replacement_truth_source']}` |"
            )
    plan_lines.extend([
        "",
        "## 受控写入目标",
        "",
        "| Path | Permission | Max addition | Required outcome |",
        "|---|---|---:|---|",
    ])
    for path, entry in sorted(write_entries.items()):
        plan_lines.append(
            f"| `{path}` | modify-only semantic consolidation | {entry['max_added_bytes']:,} bytes / {entry['max_added_lines']} lines | {'; '.join(entry['required_content'])} |"
        )
    plan_lines.extend([
        "",
        "## P3 语义复核后继续保护的 fixture",
        "",
    ])
    for path, semantics in sorted(SEMANTICALLY_PROTECTED_FIXTURES.items()):
        plan_lines.append(f"- `{path}`：{semantics}；与 canonical valid fixture 语义不同，不能直接合并删除。")
    plan_lines.extend([
        "",
        "## 五批状态",
        "",
        "| Order | Batch | Status | Remove | Modify | Commit now |",
        "|---:|---|---|---:|---:|---|",
    ])
    for row in batch_rows:
        plan_lines.append(
            f"| {row['order']} | {row['category']} | {row['status']} | {len(row['removal_entries'])} | {len(row['guarded_write_targets'])} | NO |"
        )
    plan_lines.extend([
        "",
        "`frontend_scripts`、`validation`、`generated` 为 `SKIP_NO_SAFE_SCOPE`：不执行、不提交，不为满足五批形式制造空 commit。",
        "",
        "## 预计净减少",
        "",
        f"Gross removal：{metrics['proposed_removal_files']} files / {metrics['proposed_removal_bytes']:,} bytes / {metrics['proposed_removal_lines']} lines。受控写入预算最多 {metrics['write_budget_max_bytes']:,} bytes / {metrics['write_budget_max_lines']} lines，因此预计净减少至少 4 个文件、8,646 bytes、253 行。",
        "",
        f"Before → after lower-bound：tracked files `{baseline_metrics['tracked_files']:,} → {baseline_metrics['tracked_files'] - 4:,}`；Markdown `{baseline_metrics['markdown_files']:,} → {baseline_metrics['markdown_files'] - 4:,}`。public package scripts `{public_script_count} → {public_script_count}`；validate-prefixed scripts `{validate_script_count} → {validate_script_count}`；validator files `{validator_count} → {validator_count}`（OpenAIDatabase `{oai_validator_count} → {oai_validator_count}`）；默认 Codex context `{context_bytes:,} bytes / {context_lines} lines`，净减少 `0`。",
        "",
        "这是一组低风险、低 ROI 的窄清理，不代表完成全量 L4 收敛，也不会显著降低 validator、public scripts 或默认上下文。",
        "",
        "## Deferred 与保护边界",
        "",
        f"- protected_paths.json 精确保护 **7,734** 个 tracked paths；允许变化仅 6 个精确路径。",
        f"- Deferred non-keep：**747**。Gate：`{dict(sorted(deferred_gate_counts.items()))}`。",
        f"- Disposition：`{dict(sorted(deferred_disposition_counts.items()))}`；Batch：`{dict(sorted(deferred_batch_counts.items()))}`。",
        "- 12 个其他 active project prefix、153 个 raw/raw-like 路径、30 个 FINAL_ACCEPTANCE_BUNDLE 路径、全部 inventory protected path 均不可触碰。raw content reads=0。",
        "",
        "## Validation、停止与回滚",
        "",
        "1. S03 开始前同步并重新固定 local BASE 与 live main；任一路径/blob/reference 漂移即回到 S02 审计。",
        "2. 每个 active batch 只允许其 `allowed_changed_paths`，普通单父、单批单 commit；三个空批次不得提交。",
        "3. Documents 必须保留 CHANGELOG 的 v1.1.5 Part 1 Stage 0 版本摘要。",
        "4. Governance 必须在预算内合并 current guidance，并重跑 valid、negative、escape、中文 fixture 与 routing baseline。",
        "5. 先在 disposable clean worktree 演练 apply → validate → `git revert <batch_commit>` → validate；真实工作树不做 pre-cleanup restore rehearsal。",
        "6. 发现 unique fixture、运行依赖、引用、raw、secret、范围外 diff、remote race 或 required validation 失败即停止。",
        "",
        "## 审批矩阵",
        "",
        "1. Approve documents only：只批准 1 个 legacy review 路径。",
        "2. Approve governance conditionally：批准 3 个 operational docs + 2 个 canonical write targets，前提是语义清单和预算全部通过。",
        "3. Approve both batches：仍需 S02 Stage 复审通过并另行授权开始 S03。",
        "4. Reject / request evidence：保持全部路径不变，回到只读审计。",
        "",
        "## GitHub 与 App 边界",
        "",
        "本计划不执行 Stage-level GitHub upload。后续即使形成可独立 revert 的本地 batch commits，也必须等整体 roadmap、raw 与复审全部完成后才一次性同步 GitHub main 并重装 App。",
    ])
    (args.out / "S03_cleanup_plan.md").write_text("\n".join(plan_lines) + "\n", encoding="utf-8")

    print(json.dumps({
        "status": "GENERATED",
        "source_commit": COMMIT,
        "p2_rows": len(disposition),
        "p2_nonkeep": sum(row["p2_disposition"] != "keep" for row in disposition),
        "p2_batch_review_eligible": len(original_eligible),
        "proposed_removals": len(PROPOSED_REMOVALS),
        "guarded_write_targets": len(WRITE_TARGETS),
        "semantic_reclassified_protected": len(SEMANTICALLY_PROTECTED_FIXTURES),
        "deferred_nonkeep": len(deferred_entries),
        "protected_paths": len(protected_entries),
        "raw_content_reads": 0,
        "metrics": metrics,
        "s03_execution_authorized": False,
    }, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

